INSERT INTO `brands` (`id`, `name`, `name_ar`, `slug`, `image_url`, `created_at`, `updated_at`, `description`, `description_ar`, `website_url`, `is_active`, `priority`, `brand_type`, `banner_url`, `banner_url_mobile`, `image_url_ar`, `banner_url_ar`) VALUES
(1, '3MF', '', '3mf', 'https://api.mariotstore.com/uploads/brands/3mf.webp', '2026-03-09 07:39:12', '2026-05-30 06:48:54', 'A highly reliable brand known for producing high-quality dry store and kitchen storage solutions. 3MF specializes in durable, food-grade shelving, modular storage systems, and heavy-duty organizational infrastructure that form the backbone of efficient commercial kitchens and pantries. Their meticulous attention to material strength and hygiene standards ensures that their products can withstand the rigorous demands of high-volume storage, making them a preferred choice for large-scale catering operations, hotels, and mass production facilities seeking to optimize their workspace and maintain strict sanitary compliance.', 'علامة تجارية موثوقة للغاية ومعروفة بإنتاج حلول تخزين المطبخ والمتاجر الجافة عالية الجودة. تتخصص 3MF في الأرفف المتينة المخصصة للطعام، وأنظمة التخزين المعيارية، والبنية التحتية التنظيمية شديدة التحمل التي تشكل العمود الفقري للمطابخ التجارية والمخازن الفعالة. ويضمن اهتمامهم الدقيق بمتانة المواد ومعايير النظافة قدرة منتجاتهم على تحمل المتطلبات الصارمة للتخزين بكميات كبيرة، مما يجعلها الخيار المفضل لعمليات تقديم الطعام واسعة النطاق والفنادق ومرافق الإنتاج الضخم التي تسعى إلى تحسين مساحة العمل الخاصة بها والحفاظ على الامتثال الصحي الصارم.', '', 1, 9, 'Cooking, Laundry & Dish Washer', NULL, NULL, NULL, NULL),
(2, 'ALTO-SHAAM', '', 'alto-shaam', 'https://api.mariotstore.com/uploads/brands/Alto-Shaam.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Founded in 1955 by Jerry Maahs, Alto-Shaam pioneered the revolutionary Halo HeatÂ® technology, which uses low-density thermal cables to provide gentle, precise, and evenly distributed heat. They are a world leader in Cook & Hold ovens, smokers, heated holding cabinets, and advanced multi-cook chilling solutions. Dedicated to maximizing food quality and reducing shrinkage, Alto-Shaam\'s equipment allows chefs to prepare food ahead of time and hold it perfectly for hours without drying out or overcooking. Their relentless innovation continues to shape the commercial foodservice industry globally.', 'تأسست شركة Alto-Shaam عام 1955 على يد جيري ماهس، وهي رائدة في تقنية Halo Heat® الثورية، والتي تستخدم كابلات حرارية منخفضة الكثافة لتوفير حرارة لطيفة ودقيقة وموزعة بالتساوي. إنهم رواد عالميون في أفران Cook & Hold، والمدخنين، وخزائن التثبيت الساخنة، وحلول التبريد المتقدمة متعددة الطهي. إن معدات ألتو شام المخصصة لتحسين جودة الطعام وتقليل الانكماش، تسمح للطهاة بإعداد الطعام مسبقًا والاحتفاظ به بشكل مثالي لساعات دون أن يجف أو يطهى أكثر من اللازم. يستمر ابتكارهم المستمر في تشكيل صناعة الخدمات الغذائية التجارية على مستوى العالم.', '', 1, NULL, 'All', '', NULL, NULL, NULL),
(3, 'Anfim', '', 'anfim', 'https://api.mariotstore.com/uploads/brands/anfilm.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Born in Milan over 50 years ago, Anfim is dedicated exclusively to the art and science of espresso grinding. They manufacture premium, handmade grinders designed explicitly for professional baristas and high-end cafes. Known for their robust Italian engineering, heavy-duty motors, and highly precise titanium burrs, Anfim ensures consistent dosing, minimal heat generation, and unparalleled flavor extraction. Trusted in barista championships, Anfim remains a symbol of classic Italian coffee tradition blended meticulously with modern performance needs.', 'ولدت أنفيم في ميلانو منذ أكثر من 50 عامًا، وهي متخصصة حصريًا في فن وعلم طحن الإسبريسو. إنهم يصنعون مطاحن فاخرة مصنوعة يدويًا ومصممة خصيصًا لصانعي القهوة المحترفين والمقاهي الراقية. تشتهر شركة Anfim بهندستها الإيطالية القوية، ومحركاتها شديدة التحمل، ومثاقبها عالية الدقة من التيتانيوم، وتضمن جرعات متسقة، وتوليد الحد الأدنى من الحرارة، واستخلاص نكهة لا مثيل لها. تحظى أنفيم بثقة في بطولات باريستا، وتظل رمزًا لتقاليد القهوة الإيطالية الكلاسيكية الممزوجة بدقة مع احتياجات الأداء الحديثة.', '', 1, 1, 'All', '', '', NULL, NULL),
(4, 'APW Wyott', '', 'apw-wyott', 'https://api.mariotstore.com/uploads/brands/apwwyott.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'With a rich heritage spanning several decades, APW Wyott is a leading supplier of innovative and highly dependable commercial cooking and warming equipment. Their comprehensive product line includes heavy-duty conveyor toasters, hot dog rollers, soup warmers, griddles, and holding stations. Designed for maximum throughput and longevity, APW Wyott\'s solutions are absolutely essential for fast-paced quick-service restaurants, convenience stores, and institutional cafeterias that demand high performance and reliable heat distribution around the clock.', 'مع تراث غني يمتد لعدة عقود، تعد APW Wyott موردًا رائدًا لمعدات الطبخ والتدفئة التجارية المبتكرة والموثوقة للغاية. يشتمل خط إنتاجها الشامل على محمصات ناقلة للخدمة الشاقة، وبكرات الهوت دوج، وأجهزة تدفئة الحساء، والشوايات، ومحطات التثبيت. تم تصميم حلول APW Wyott لتحقيق أقصى قدر من الإنتاجية وطول العمر، وهي ضرورية للغاية للمطاعم ذات الخدمة السريعة سريعة الخطى والمتاجر الصغيرة والكافيتريات المؤسسية التي تتطلب أداءً عاليًا وتوزيعًا موثوقًا للحرارة على مدار الساعة.', '', 1, NULL, 'All', '', NULL, NULL, NULL),
(5, 'ASAKI', '', 'asaki', 'https://api.mariotstore.com/uploads/brands/asaki-logo.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Asaki is internationally renowned for providing exceptionally durable and efficient food processing equipment. Their robust product line features heavy-duty meat mincers, bone saws, vegetable prep machines, slicers, and planetary mixers. Engineered to withstand the rigorous demands of busy commercial kitchens, high-volume butcheries, and medium-scale food production facilities, Asaki emphasizes operator safety, ease of cleaning, and raw mechanical power to drastically reduce manual labor and prep times.', 'شركة Asaki مشهورة عالميًا بتوفير معدات تجهيز الأغذية المتينة والفعالة بشكل استثنائي. يتميز خط إنتاجهم القوي بمفارم اللحوم شديدة التحمل، ومناشير العظام، وآلات تحضير الخضروات، وتقطيع الشرائح، والخلاطات الكوكبية. تم تصميم Asaki لتحمل المتطلبات الصارمة للمطابخ التجارية المزدحمة، والمجازر كبيرة الحجم، ومنشآت إنتاج الأغذية متوسطة الحجم، وتؤكد على سلامة المشغل، وسهولة التنظيف، والطاقة الميكانيكية الخام لتقليل العمل اليدوي وأوقات الإعداد بشكل كبير.', '', 1, NULL, 'All', '', NULL, NULL, NULL),
(6, 'BERJAYA', '', 'berjaya', 'https://api.mariotstore.com/uploads/brands/Berjaya-Logo.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'A comprehensive and dominant provider of commercial food service equipment, Berjaya offers an incredibly vast range of products encompassing heavy-duty commercial refrigeration, bakery deck ovens, display showcases, and custom stainless steel fabrication. Based in Malaysia, they are a one-stop-shop brand highly trusted across Asia, the Middle East, and beyond, celebrated for delivering reliable, cost-effective, and robust catering solutions that suit both small cafes and massive hotel kitchens.', 'كمزود شامل ومهيمن لمعدات الخدمات الغذائية التجارية، تقدم برجايا مجموعة واسعة بشكل لا يصدق من المنتجات التي تشمل التبريد التجاري الثقيل، وأفران سطح المخابز، وواجهات العرض، وتصنيع الفولاذ المقاوم للصدأ المخصص. يقع مقرها في ماليزيا، وهي علامة تجارية شاملة تحظى بثقة كبيرة في جميع أنحاء آسيا والشرق الأوسط وخارجها، وتشتهر بتقديم حلول طعام موثوقة وفعالة من حيث التكلفة وقوية تناسب المقاهي الصغيرة ومطابخ الفنادق الضخمة.', '', 1, NULL, 'All', '', NULL, NULL, NULL),
(7, 'blendtec', '', 'blendtec', 'https://api.mariotstore.com/uploads/brands/Blendec-logo.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Famous for their highly powerful and technologically advanced commercial blenders, Blendtec is the preferred choice of top international beverage chains. By inventing the square blending jar and employing ultra-thick blunt safety blades spinning at extreme velocities, Blendtec machines are designed to obliterate ice, frozen fruit, and tough ingredients. Their blenders produce the smoothest smoothies, frappes, and purees in seconds, supported by programmable cycles for perfect consistency every single time.', 'تشتهر Blendtec بخلاطاتها التجارية القوية للغاية والمتقدمة تقنيًا، وهي الخيار المفضل لأفضل سلاسل المشروبات العالمية. من خلال اختراع وعاء الخلط المربع واستخدام شفرات أمان حادة سميكة جدًا تدور بسرعات قصوى، تم تصميم آلات Blendtec لطمس الثلج والفواكه المجمدة والمكونات القاسية. تنتج الخلاطات الخاصة بهم أنعم العصائر والفطائر والمهروس في ثوانٍ، مدعومة بدورات قابلة للبرمجة لتحقيق الاتساق المثالي في كل مرة.', '', 1, NULL, 'All', '', NULL, NULL, NULL),
(8, 'BREMA', '', 'brema', 'https://api.mariotstore.com/uploads/brands/brema.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Since 1985, the Italian experts at Brema have been designing and manufacturing premium commercial ice-making machines with uncompromising standards. With a relentless focus on material quality, water efficiency, and environmental sustainability, Brema produces crystal-clear ice cubes, flakes, and pebbles. Their advanced spray and auger systems are essential for upscale cocktail bars, fine dining restaurants, fish markets, and medical facilities globally that demand pristine, slow-melting ice.', 'منذ عام 1985، يقوم الخبراء الإيطاليون في شركة Brema بتصميم وتصنيع آلات صنع الثلج التجارية المتميزة بمعايير لا تقبل المساومة. مع التركيز المستمر على جودة المواد، وكفاءة استخدام المياه، والاستدامة البيئية، تنتج بريما مكعبات ثلج ورقائق وحصى واضحة تمامًا. تعد أنظمة الرش والثقب المتقدمة الخاصة بها ضرورية لحانات الكوكتيل الراقية والمطاعم الفاخرة وأسواق السمك والمرافق الطبية على مستوى العالم التي تتطلب ثلجًا نقيًا وبطيء الذوبان.', '', 1, NULL, 'All', '', NULL, NULL, NULL),
(9, 'CAMRY', '', 'camry', 'https://api.mariotstore.com/uploads/brands/camry.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Camry offers a specialized wide range of highly reliable kitchen appliances focused primarily on precision measurement and essential home-style commercial tools. They are particularly well-regarded in the industry for their highly accurate digital portion control scales, mechanical scales, and timing devices. These precision instruments are absolutely indispensable for recipe consistency, strict cost management, and quality control in commercial bakeries, ghost kitchens, and fine dining prep stations.', 'تقدم Camry مجموعة واسعة متخصصة من أدوات المطبخ الموثوقة للغاية والتي تركز بشكل أساسي على القياس الدقيق والأدوات التجارية الأساسية ذات الطراز المنزلي. وهي تحظى بتقدير كبير في الصناعة على وجه الخصوص بسبب موازينها الرقمية عالية الدقة للتحكم في الأجزاء، والموازين الميكانيكية، وأجهزة التوقيت. لا غنى عن هذه الأدوات الدقيقة تمامًا لتحقيق اتساق الوصفات، وإدارة التكاليف الصارمة، ومراقبة الجودة في المخابز التجارية، ومطابخ الأشباح، ومحطات إعداد الطعام الفاخرة.', '', 1, NULL, 'All', '', NULL, NULL, NULL),
(10, 'capinox', '', 'capinox', 'https://api.mariotstore.com/uploads/brands/capinox.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Capinox provides top-grade, custom stainless steel fabrication meticulously tailored for demanding commercial kitchen environments. Their bespoke worktables, deep-basin sinks, high-extraction exhaust hoods, and modular shelving units are constructed exclusively using high-grade AISI 304 stainless steel. This commitment to premium materials ensures absolute hygiene, flawless rust resistance, and unyielding structural integrity under the punishing conditions of heavy daily culinary operations.', 'توفر Capinox تصنيعًا مخصصًا من الفولاذ المقاوم للصدأ عالي الجودة ومصممًا بدقة لبيئات المطبخ التجارية الصعبة. تم تصنيع طاولات العمل المخصصة، وأحواض الأحواض العميقة، وأغطية العادم عالية الاستخراج، ووحدات الرفوف المعيارية حصريًا باستخدام الفولاذ المقاوم للصدأ AISI 304 عالي الجودة. ويضمن هذا الالتزام بالمواد المتميزة النظافة المطلقة، ومقاومة الصدأ التي لا تشوبها شائبة، والسلامة الهيكلية التي لا تنضب في ظل الظروف القاسية لعمليات الطهي اليومية الثقيلة.', '', 1, NULL, 'All', '', NULL, NULL, NULL),
(11, 'COFRIMELL', '', 'cofrimell', 'https://api.mariotstore.com/uploads/brands/cofrimell.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Based in Rome, Cofrimell has been a global leader in manufacturing high-quality commercial cold beverage dispensers and slush (granita) machines since 1981. Their visually appealing, high-capacity cooling systems feature robust polycarbonate bowls, powerful compressors, and intuitive controls. They are staple, highly profitable equipment in cafes, hotels, convenience stores, and amusement parks worldwide, designed to attract impulse purchases through clear, vibrant display.', 'يقع مقر شركة Cofrimell في روما، وهي شركة رائدة عالميًا في تصنيع موزعات المشروبات الباردة التجارية عالية الجودة وآلات السلاش (الجرانيتا) منذ عام 1981. تتميز أنظمة التبريد ذات السعة العالية الجذابة بصريًا بأوعية قوية من البولي كربونات وضواغط قوية وأدوات تحكم بديهية. إنها معدات أساسية ومربحة للغاية في المقاهي والفنادق والمتاجر الصغيرة والمتنزهات في جميع أنحاء العالم، وهي مصممة لجذب المشتريات الدافعة من خلال عرض واضح ونابض بالحياة.', '', 1, NULL, 'All', '', NULL, NULL, NULL),
(12, 'Desmon', '', 'desmon', 'https://api.mariotstore.com/uploads/brands/desmon.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Desmon is a premier European specialist in professional commercial refrigeration, advanced blast chillers, and large-scale modular cold rooms. They utilize highly advanced high-density polyurethane insulation and incredibly energy-efficient refrigeration compressors. Their precision-engineered equipment is vital for rapid, safe food preservation, extending shelf life, and strict HACCP compliance in elite restaurant settings, massive catering events, and high-end hotel chains.', 'يعتبر Desmon شركة أوروبية رائدة متخصصة في مجال التبريد التجاري الاحترافي، ومبردات الانفجار المتقدمة، وغرف التبريد المعيارية واسعة النطاق. إنها تستخدم عزلًا متقدمًا للغاية من مادة البولي يوريثين عالي الكثافة وضواغط تبريد موفرة للطاقة بشكل لا يصدق. تعد معداتهم المصممة بدقة أمرًا حيويًا لحفظ الطعام بسرعة وأمان، وإطالة مدة الصلاحية، والامتثال الصارم لنظام تحليل المخاطر ونقاط التحكم الحرجة (HACCP) في إعدادات المطاعم الراقية، وفعاليات تقديم الطعام الضخمة، وسلاسل الفنادق الراقية.', '', 1, NULL, 'All', '', NULL, NULL, NULL),
(13, 'EASYLINE', '', 'easyline', 'https://api.mariotstore.com/uploads/brands/easyline.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Easyline by Fimar offers a diverse range of reliable, cost-effective light commercial equipment. Designed perfectly for small cafes, kiosks, and home businesses, their product line includes planetary mixers, induction hobs, and vacuum packers that deliver professional results without the industrial price tag.', 'تقدم شركة Easyline من Fimar مجموعة متنوعة من المعدات التجارية الخفيفة الموثوقة والفعالة من حيث التكلفة. تم تصميمها بشكل مثالي للمقاهي الصغيرة والأكشاك والشركات المنزلية، ويشمل خط إنتاجها الخلاطات الكوكبية، ومواقد الحث، وآلات تعبئة الفراغ التي تقدم نتائج احترافية دون دفع الأسعار الصناعية.', '', 1, NULL, 'All', '', NULL, NULL, NULL),
(14, 'Electrolux', '', 'electrolux', 'https://api.mariotstore.com/uploads/brands/electrolux.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Electrolux Professional is a global powerhouse delivering complete, fully integrated, and highly intelligent solutions for professional kitchens and commercial laundries. Known for deeply pioneering sustainable technologies, their premium combi ovens, rapid boiling pans, and high-efficiency rack-type dishwashers are designed for ultimate operational performance. They dramatically lower running costs through reduced water, energy, and detergent consumption while maximizing output.', 'تعد شركة Electrolux Professional شركة عالمية تقدم حلولاً كاملة ومتكاملة تمامًا وذكية للغاية للمطابخ الاحترافية والمغاسل التجارية. تشتهر الشركة بتقنياتها المستدامة الرائدة، حيث تم تصميم أفرانها المجمعة المتميزة، وأواني الغليان السريعة، وغسالات الأطباق ذات الرفوف عالية الكفاءة لتحقيق الأداء التشغيلي النهائي. إنها تقلل تكاليف التشغيل بشكل كبير من خلال تقليل استهلاك المياه والطاقة والمنظفات مع زيادة الإنتاج إلى الحد الأقصى.', '', 1, NULL, 'All', '', NULL, NULL, NULL),
(15, 'GG F', '', 'gg-f', 'https://api.mariotstore.com/uploads/brands/ggf-logo.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'GGF is a specialized Italian manufacturer globally recognized for producing highly robust equipment tailored for pizzerias and bakeries. Their high-heat electric deck ovens, powerful spiral dough mixers, and precision dough rollers are engineered to create authentic, perfect crusts and handle heavy, continuous daily use.', 'GGF هي شركة تصنيع إيطالية متخصصة معترف بها عالميًا لإنتاج معدات قوية للغاية مصممة خصيصًا لمطاعم البيتزا والمخابز. تم تصميم أفران سطحها الكهربائية ذات الحرارة العالية، وخلاطات العجين الحلزونية القوية، وبكرات العجين الدقيقة لإنشاء قشور أصلية ومثالية والتعامل مع الاستخدام اليومي الثقيل والمستمر.', '', 1, NULL, 'All', '', NULL, NULL, NULL),
(16, 'EMPERO', '', 'empero', 'https://api.mariotstore.com/uploads/brands/empero.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Empero is a massive and leading Turkish manufacturer of heavy-duty commercial kitchen setups. Operating from state-of-the-art production facilities, they manufacture virtually everything for a professional kitchen, from robust industrial gas cooking ranges and convection ovens to incredibly advanced flight-type dishwashing systems. They uniquely combine stringent European manufacturing quality standards with highly competitive pricing and rapid global distribution.', 'Empero هي شركة تركية ضخمة ورائدة في مجال تصنيع تجهيزات المطابخ التجارية الثقيلة. تعمل من خلال مرافق إنتاج حديثة، وتقوم بتصنيع كل شيء تقريبًا لمطبخ احترافي، بدءًا من نطاقات الطهي القوية بالغاز الصناعي والأفران الحرارية وحتى أنظمة غسل الأطباق المتطورة بشكل لا يصدق. فهي تجمع بشكل فريد بين معايير جودة التصنيع الأوروبية الصارمة والأسعار التنافسية للغاية والتوزيع العالمي السريع.', '', 1, NULL, 'All', '', NULL, NULL, NULL),
(18, 'ACE FILTERS', '', 'ace-filters', 'https://api.mariotstore.com/uploads/brands/Falater.webp', '2026-03-09 07:39:12', '2026-05-30 06:49:05', 'Ace Filters provides premium filtration technology specifically designed for commercial deep fryers. Their highly efficient filter papers and powders drastically extend the life of cooking oil by capturing microscopic burn particles, resulting in beautifully fried food, massive cost savings, and improved environmental impact.', 'توفر Ace Filters تقنية ترشيح متميزة مصممة خصيصًا للمقالي العميقة التجارية. تعمل أوراق الترشيح والمساحيق عالية الكفاءة على إطالة عمر زيت الطهي بشكل كبير من خلال التقاط جزيئات الحروق المجهرية، مما يؤدي إلى طعام مقلي بشكل جميل، وتوفير كبير في التكاليف، وتحسين التأثير البيئي.', '', 1, 5, 'All, Cooking', NULL, '', NULL, NULL),
(19, 'fimar', '', 'fimar', 'https://api.mariotstore.com/uploads/brands/fimar.webp', '2026-03-09 07:39:12', '2026-05-30 06:49:12', 'For over 40 years, Fimar has been a cornerstone of the Italian food processing industry. They manufacture incredibly sturdy meat mincers, bone saws, pasta machines, and robust vegetable cutters. Their heavy-duty equipment is a mandatory workhorse in busy butcheries, deli counters, and traditional Italian restaurant kitchens.', 'لأكثر من 40 عامًا، كانت شركة Fimar بمثابة حجر الزاوية في صناعة تجهيز الأغذية الإيطالية. إنهم يصنعون مفرمة لحم قوية بشكل لا يصدق ومناشير العظام وآلات المعكرونة وقواطع الخضار القوية. تعتبر معداتهم الثقيلة بمثابة العمود الفقري الإلزامي في الجزارة المزدحمة وعدادات المأكولات الجاهزة ومطابخ المطاعم الإيطالية التقليدية.', '', 1, NULL, 'All', NULL, NULL, NULL, NULL),
(20, 'Frymaster', '', 'frymaster', 'https://api.mariotstore.com/uploads/brands/FRYMASTER.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Founded in 1935, Frymaster is the undisputed, gold-standard in the industry for commercial deep fryers. They revolutionized the culinary world with the open-pot fryer design and highly advanced built-in oil filtration systems. Today, their high-efficiency, digitally controlled fryers are trusted exclusively by the world\'s largest fast-food chains to deliver perfectly crispy, uniform food while saving millions of dollars globally on oil usage.', 'تأسست شركة Frymaster في عام 1935، وهي بلا منازع هي المعيار الذهبي في صناعة المقالي العميقة التجارية. لقد أحدثوا ثورة في عالم الطهي من خلال تصميم المقلاة ذات الوعاء المفتوح وأنظمة ترشيح الزيت المدمجة المتقدمة للغاية. واليوم، تحظى مقاليهم عالية الكفاءة والتي يتم التحكم فيها رقميًا بثقة حصريًا من قبل أكبر سلاسل الوجبات السريعة في العالم لتقديم طعام مقرمش وموحد تمامًا مع توفير ملايين الدولارات على مستوى العالم من استخدام الزيت.', '', 1, NULL, 'All', '', NULL, NULL, NULL),
(21, 'GEL MATIC', '', 'gel-matic', 'https://api.mariotstore.com/uploads/brands/gelmatic.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Gel Matic is a sophisticated Italian brand completely dedicated to the engineering of express blending and freezing technologies. Their advanced soft-serve ice cream, frozen yogurt, and milkshake machines are famous for extraordinary reliability, huge hourly yields, and producing exceptionally smooth, creamy textures.', 'جل ماتيك هي علامة تجارية إيطالية متطورة مخصصة بالكامل لهندسة تقنيات الخلط والتجميد السريع. تشتهر آلات الآيس كريم والزبادي المجمد والميلك شيك المتقدمة بموثوقيتها غير العادية وعوائدها الضخمة في الساعة وإنتاج قوام كريمي ناعم بشكل استثنائي.', '', 1, NULL, 'All', '', NULL, NULL, NULL),
(23, 'Hamilton Beach', '', 'hamilton-beach', 'https://api.mariotstore.com/uploads/brands/hamilton-logo.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Trusted worldwide for well over a century, Hamilton Beach Commercial specializes in incredibly high-performance culinary blenders, drink mixers, and beverage equipment. Their durable, high-torque motors and patented wave-action blending systems continually force ingredients down into the blades. This makes their heavy-duty equipment an absolute, unbreakable necessity for busy cocktail bars, global smoothie shop franchises, and high-prep commercial kitchens.', 'تحظى شركة Hamilton Beach Commercial بالثقة في جميع أنحاء العالم لأكثر من قرن من الزمان، وهي متخصصة في خلاطات الطهي وخلاطات المشروبات ومعدات المشروبات عالية الأداء بشكل لا يصدق. تعمل محركاتها المتينة ذات عزم الدوران العالي وأنظمة المزج ذات الحركة الموجية الحاصلة على براءة اختراع على دفع المكونات باستمرار إلى الشفرات. وهذا يجعل معداتهم الثقيلة ضرورة مطلقة وغير قابلة للكسر لحانات الكوكتيل المزدحمة، وامتيازات محلات العصائر العالمية، والمطابخ التجارية عالية الإعداد.', '', 1, NULL, 'All', '', NULL, NULL, NULL),
(24, 'Hatco', '', 'hatco', 'https://api.mariotstore.com/uploads/brands/hacto.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Since 1950, Hatco has been the foremost innovator and expert in holding, warming, and visually displaying food products. Their highly innovative decorative heat lamps, thermostatically controlled heated shelves, and powerful booster water heaters ensure that prepared food is kept safely at optimum serving temperatures. Crucially, Hatco engineering guarantees this heat retention without ever compromising food quality, texture, or drying it out before serving.', 'منذ عام 1950، كانت هاتكو هي الرائدة في مجال الابتكار والخبرة في حمل المنتجات الغذائية وتسخينها وعرضها بصريًا. تضمن مصابيح الحرارة المزخرفة المبتكرة للغاية، والأرفف الساخنة التي يتم التحكم فيها حرارياً، وسخانات المياه القوية أن يتم حفظ الطعام الجاهز بأمان في درجات حرارة التقديم المثالية. والأهم من ذلك، أن هندسة Hatco تضمن الاحتفاظ بالحرارة دون المساس بجودة الطعام أو ملمسه أو تجفيفه قبل التقديم.', '', 1, NULL, 'All', '', NULL, NULL, NULL),
(25, 'HENNY PENNY', '', 'henny-penny', 'https://api.mariotstore.com/uploads/brands/hennypenny.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Henny Penny is world-famous for inventing the first commercial pressure fryer in 1957, a technological leap that forever revolutionized the fast-food chicken industry. Today, their incredibly advanced pressure fryers, high-volume open fryers, and smart heated holding cabinets form the highly reliable backbone of rapid, large-scale fried chicken and protein production for top-tier global restaurant and supermarket franchises.', 'يشتهر هيني بيني عالميًا باختراع أول مقلاة ضغط تجارية في عام 1957، وهي قفزة تكنولوجية أحدثت ثورة إلى الأبد في صناعة الدجاج للوجبات السريعة. واليوم، تشكل مقالي الضغط المتقدمة بشكل لا يصدق، والمقالي المفتوحة ذات الحجم الكبير، وخزائن التخزين الذكية المسخنة العمود الفقري الموثوق به للغاية لإنتاج الدجاج المقلي والبروتين السريع على نطاق واسع لامتيازات المطاعم والسوبر ماركت العالمية من الدرجة الأولى.', '', 1, NULL, 'All', '', NULL, NULL, NULL),
(26, 'HCONVED', '', 'hconved', 'https://api.mariotstore.com/uploads/brands/hoonved.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Hoonved (often listed under various spellings) is an esteemed Italian manufacturer specializing entirely in high-end commercial warewashing. From rapid glasswashers for busy cocktail bars to massive rack-conveyor dishwashers for hospitals, their machines are engineered for flawless hygiene, water conservation, and absolute reliability.', 'Hoonved (غالبًا ما يتم إدراجها تحت تهجئات مختلفة) هي شركة تصنيع إيطالية مرموقة متخصصة بالكامل في غسيل الأدوات التجارية المتطورة. بدءًا من غسالات الزجاج السريعة لحانات الكوكتيل المزدحمة وحتى غسالات الأطباق الضخمة ذات الحامل المتحرك للمستشفيات، تم تصميم أجهزتها لتحقيق نظافة لا تشوبها شائبة، والحفاظ على المياه، والموثوقية المطلقة.', '', 1, NULL, 'All', '', NULL, NULL, NULL),
(27, 'IMESA', NULL, 'imesa', 'https://api.mariotstore.com/uploads/brands/imesa.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Imesa is a leading European name in professional and industrial laundry equipment. They manufacture highly advanced, heavy-duty washing machines, tumble dryers, and flatwork ironers. Driven by smart touchscreens and energy-efficient water cycles, Imesa systems are heavily trusted by luxury hotels, cruise ships, and commercial laundromats.', 'Imesa هو اسم أوروبي رائد في مجال معدات الغسيل المهنية والصناعية. إنهم يصنعون غسالات ومجففات ملابس وآلات كي الملابس المسطحة المتقدمة للغاية. بفضل شاشات اللمس الذكية ودورات المياه الموفرة للطاقة، تحظى أنظمة Imesa بثقة كبيرة من قبل الفنادق الفاخرة وسفن الرحلات البحرية والمغاسل التجارية.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(28, 'IMPERIAL', NULL, 'imperial', 'https://api.mariotstore.com/uploads/brands/IMPERIAL.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Imperial Commercial Cooking Equipment is an iconic, heavy-duty American brand. Famous for their incredibly durable cast-iron grates and high-BTU burners, Imperial supplies massive gas ranges, convection ovens, and deep fryers that form the indestructible cooking backbone of huge steakhouses and high-volume diners.', 'تعد شركة Imperial Commercial Cooking Equipment علامة تجارية أمريكية مميزة للخدمة الشاقة. تشتهر شركة Imperial بشبكاتها المصنوعة من الحديد الزهر والمواقد ذات الطاقة الحرارية العالية، وتوفر نطاقات غاز ضخمة وأفران حرارية ومقالي عميقة تشكل العمود الفقري للطهي غير القابل للتدمير لمطاعم شرائح اللحم الضخمة والمطاعم ذات الحجم الكبير.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(29, 'INFRICO', NULL, 'infrico', 'https://api.mariotstore.com/uploads/brands/inofrigo.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Infrico is Spain\'s absolute market leader in the commercial refrigeration sector. They specialize in high-quality refrigerated display cases, cold prep tables, and massive reach-in freezers. Infrico utilizes highly advanced, environmentally friendly refrigerants and incredibly deep insulation to guarantee perfect cold bridging and food safety.', 'Infrico هي الشركة الرائدة في السوق الإسبانية في قطاع التبريد التجاري. إنهم متخصصون في علب العرض المبردة عالية الجودة، وطاولات الإعداد البارد، والمجمدات الضخمة التي يمكن الوصول إليها. تستخدم Infrico مبردات متقدمة للغاية وصديقة للبيئة وعزلًا عميقًا بشكل لا يصدق لضمان التوصيل البارد المثالي وسلامة الأغذية.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(30, 'JOSPER', NULL, 'josper', 'https://api.mariotstore.com/uploads/brands/josper.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Josper completely modernized the ancient art of charcoal cooking by combining an oven and a grill in a single machine. Universally beloved by Michelin-star chefs and premium steakhouses, Josper ovens operate at extreme temperatures using 100% charcoal, delivering an unmatched, incredibly rich smoky flavor and perfect sear.', 'قام Josper بتحديث الفن القديم للطهي بالفحم بالكامل من خلال الجمع بين الفرن والشواية في آلة واحدة. تحظى أفران جوسبر بشعبية كبيرة لدى الطهاة الحائزين على نجمة ميشلان ومطاعم شرائح اللحم الفاخرة، وتعمل في درجات حرارة قصوى باستخدام الفحم بنسبة 100%، مما يوفر نكهة دخانية لا مثيل لها وغنية بشكل لا يصدق وحرق مثالي.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(31, 'KITCHENAID', NULL, 'kitchenaid', 'https://api.mariotstore.com/uploads/brands/Kitchen-Aid.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'An iconic, deeply respected American brand established in 1919, KitchenAid Commercial delivers highly premium planetary mixers and heavy-duty culinary tools. Known for their timeless, classic aesthetic and practically indestructible all-metal-gear construction, their commercial mixers offer unmatched torque and reliability. They remain beloved and heavily relied upon by professional pastry chefs, artisanal bakers, and top culinary schools worldwide.', 'علامة تجارية أمريكية مميزة تحظى باحترام كبير تأسست عام 1919، تقدم KitchenAid Commercial خلاطات كوكبية عالية الجودة وأدوات طهي عالية التحمل. تشتهر خلاطاتها التجارية بجماليتها الكلاسيكية الخالدة وبنيتها المعدنية غير القابلة للتدمير عمليًا، وتوفر عزم دوران وموثوقية لا مثيل لهما. يظلون محبوبين ويعتمد عليهم بشدة طهاة المعجنات المحترفون والخبازون الحرفيون وأفضل مدارس الطهي في جميع أنحاء العالم.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(32, 'LA MARZOCCO', NULL, 'la-marzocco', 'https://api.mariotstore.com/uploads/brands/La-Marzocco.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Founded in 1927 in Florence, Italy, La Marzocco stands as the absolute gold standard in handmade, premium commercial espresso machines. They proudly pioneered the horizontal boiler and dual-boiler systems, dramatically changing coffee extraction. Today, their iconic, hand-assembled machinesâ€”like the legendary Linea Classic and the advanced Stradaâ€”are the beloved centerpieces of the world\'s absolute finest specialty coffee shops and roasteries.', 'تأسست شركة La Marzocco عام 1927 في فلورنسا بإيطاليا، وهي تمثل المعيار الذهبي المطلق في آلات الإسبريسو التجارية المتميزة المصنوعة يدويًا. لقد كانوا بكل فخر روادًا في أنظمة الغلايات الأفقية والغلايات المزدوجة، مما أدى إلى تغيير جذري في عملية استخلاص القهوة. واليوم، أصبحت أجهزتهم المميزة التي تم تجميعها يدويًا - مثل Linea Classic الأسطورية وStrada المتقدمة - هي القطع المركزية المحبوبة في أرقى المقاهي والمحامص المتخصصة في العالم.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(33, 'La Minerva', NULL, 'la-minerva', 'https://api.mariotstore.com/uploads/brands/LA-MINERVA.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'La Minerva (Minerva Omega Group) is an incredibly prestigious Italian manufacturer of meat and food processing machinery. Their heavy-duty meat grinders, huge bandsaws, hamburger pressers, and slicers are a testament to legendary mechanical engineering, heavily relied upon by industrial butcheries and large-scale meat packers.', 'La Minerva (Minerva Omega Group) هي شركة تصنيع إيطالية مرموقة بشكل لا يصدق لآلات تصنيع اللحوم والأغذية. تعد مطاحن اللحوم شديدة التحمل، والمناشير الحزامية الضخمة، ومكابس الهامبرغر، وقطاعات اللحم بمثابة شهادة على الهندسة الميكانيكية الأسطورية، التي تعتمد عليها بشكل كبير الجزارون الصناعيون وعمال تعبئة اللحوم على نطاق واسع.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(34, 'LA CIMBALI', NULL, 'la-cimbali', 'https://api.mariotstore.com/uploads/brands/lacimbali.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'With an illustrious history spanning over 100 years, La Cimbali represents the absolute pinnacle of traditional Italian espresso culture and engineering. They are unparalleled pioneers in high-end traditional espresso machines, super-automatic cappuccino machines, and patented thermal balancing systems. Their massive, beautiful machines are specifically designed to deliver exceptional coffee quality consistently, even at incredibly high, non-stop volumes.', 'مع تاريخ عريق يمتد لأكثر من 100 عام، تمثل La Cimbali القمة المطلقة لثقافة وهندسة الإسبريسو الإيطالية التقليدية. إنهم رواد لا مثيل لهم في آلات الإسبريسو التقليدية المتطورة، وآلات الكابتشينو فائقة الأوتوماتيكية، وأنظمة التوازن الحراري الحاصلة على براءة اختراع. تم تصميم أجهزتهم الضخمة والجميلة خصيصًا لتقديم جودة قهوة استثنائية باستمرار، حتى بكميات كبيرة جدًا وبدون توقف.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(35, 'Longoni', NULL, 'longoni', 'https://api.mariotstore.com/uploads/brands/Longoni-Brand.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Longoni is an Italian specialist in the art of refrigerated display. They manufacture exquisitely designed, towering vertical glass showcases specifically for pastry shops, gelaterias, and premium wine cellars. Their cabinets combine flawless cooling technology with elegant lighting to dramatically boost impulse sales.', 'لونجوني هو إيطالي متخصص في فن العرض المبرد. إنهم يصنعون واجهات عرض زجاجية عمودية مصممة بشكل رائع خصيصًا لمحلات المعجنات والجيلاتيريات وأقبية النبيذ الفاخرة. تجمع خزاناتهم بين تقنية التبريد الخالية من العيوب والإضاءة الأنيقة لتعزيز المبيعات الدافعة بشكل كبير.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(37, 'MAHLKONIG', NULL, 'mahlkonig', 'https://api.mariotstore.com/uploads/brands/MAHLKONIG-vector-logo.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'MahlkÃ¶nig is heavily regarded as the \'King of Grinders\' in the specialty coffee industry. Handcrafted in Germany, their grinders (like the iconic EK43) feature massive, precision-engineered flat burrs that provide the most even particle distribution in the world, making them mandatory in championship-level coffee shops.', 'يُنظر إلى مالكونيغ على أنه \"ملك المطاحن\" في صناعة القهوة المتخصصة. تتميز مطاحنهم المصنوعة يدويًا في ألمانيا (مثل المطاحن EK43 الشهيرة) بشفرات مسطحة ضخمة ومصممة بدقة توفر توزيعًا متساويًا للجسيمات في العالم، مما يجعلها إلزامية في المقاهي على مستوى البطولة.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(38, 'MARIOT', NULL, 'mariot', 'https://api.mariotstore.com/uploads/brands/mariot.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Mariot is our incredibly proud, specialized house brand. Deeply understanding the heavy demands of Middle Eastern kitchens, Mariot produces a highly reliable range of cost-effective, heavy-duty kitchen equipment, from high-heat cooking ranges to durable refrigeration solutions, all backed by our exceptional local warranty.', 'ماريوت هي علامتنا التجارية المنزلية المتخصصة التي نفخر بها بشكل لا يصدق. من خلال فهمها العميق للمتطلبات الثقيلة لمطابخ الشرق الأوسط، تنتج ماريوت مجموعة موثوقة للغاية من معدات المطبخ شديدة التحمل وفعالة من حيث التكلفة، بدءًا من نطاقات الطهي عالية الحرارة وحتى حلول التبريد المتينة، وكلها مدعومة بضماننا المحلي الاستثنائي.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(39, 'MARIOT FABRICATION', NULL, 'mariot-fabrication', 'https://api.mariotstore.com/uploads/brands/fabrication.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Mariot Fabrication is our specialized, bespoke stainless steel division. We employ master welders and heavy-gauge AISI 304 stainless steel to custom-build entirely bespoke exhaust hoods, deep-basin sinks, workbenches, and structural shelving, perfectly tailored to the exact millimeter of your commercial kitchen space.', 'إن شركة Mariot Fabrication هي قسمنا المتخصص والمخصص للفولاذ المقاوم للصدأ. نحن نوظف عمال لحام محترفين وفولاذ مقاوم للصدأ AISI 304 ثقيل الحجم لبناء أغطية عادم مخصصة بالكامل، وأحواض أحواض عميقة، ومقاعد عمل، ورفوف هيكلية، مصممة بشكل مثالي لتناسب المليمتر الدقيق لمساحة مطبخك التجاري.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(40, 'MBM', NULL, 'mbm', 'https://api.mariotstore.com/uploads/brands/mbm-logo.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'MBM is a highly respected Italian manufacturer providing complete, modular cooking lines designed specifically for restaurants and large catering facilities. Part of the massive Eurotec group, their sleek, heavy-duty modular ranges allow chefs to seamlessly combine fryers, griddles, and pasta boilers into one beautiful, continuous cooking island.', 'MBM هي شركة تصنيع إيطالية تحظى باحترام كبير وتوفر خطوط طهي نموذجية كاملة مصممة خصيصًا للمطاعم ومرافق تقديم الطعام الكبيرة. جزء من مجموعة Eurotec الضخمة، تتيح مجموعاتها المعيارية الأنيقة والمتينة للطهاة الجمع بين المقالي والشوايات وغلايات المعكرونة بسلاسة في جزيرة طهي واحدة جميلة ومستمرة.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(41, 'MENUMASTER', NULL, 'menumaster', 'https://api.mariotstore.com/uploads/brands/menumaster.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'A prestigious brand falling under the ACP umbrella, Menumaster leads the global industry in massive-duty, high-speed commercial microwave ovens and accelerated cooking solutions. Their heavy-duty, stainless steel microwaves are over-engineered specifically to withstand hundreds of rigorous uses per day. They provide rapid, perfectly even heating which is absolutely crucial for maintaining speed-of-service in busy quick-service restaurants.', 'علامة تجارية مرموقة تندرج تحت مظلة ACP، تقود Menumaster الصناعة العالمية في أفران الميكروويف التجارية عالية السرعة وحلول الطهي المتسارعة. تم تصميم أفران الميكروويف شديدة التحمل المصنوعة من الفولاذ المقاوم للصدأ خصيصًا لتحمل مئات الاستخدامات الصارمة يوميًا. إنها توفر تسخينًا سريعًا ومتوازنًا تمامًا وهو أمر بالغ الأهمية للحفاظ على سرعة الخدمة في مطاعم الخدمة السريعة المزدحمة.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(42, 'MERRYCHEF', NULL, 'merrychef', 'https://api.mariotstore.com/uploads/brands/merrychef.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Merrychef has completely revolutionized the modern culinary landscape with its unmatched, ultra-high-speed accelerated cooking ovens. By ingeniously combining microwave, convection, and finely tuned air impingement technologies in a single compact footprint, their ovens can cook, toast, and bake food up to 20 times faster than conventional methods, making them the ultimate solution for intense, fast-casual dining environments.', 'لقد أحدثت Merrychef ثورة كاملة في مشهد الطهي الحديث من خلال أفران الطهي السريعة للغاية التي لا مثيل لها. من خلال الجمع ببراعة بين تقنيات الميكروويف والحمل الحراري وتقنيات اصطدام الهواء المضبوطة بدقة في مساحة واحدة مدمجة، يمكن لأفرانها طهي الطعام وتحميصه وخبزه بسرعة تصل إلى 20 مرة أسرع من الطرق التقليدية، مما يجعلها الحل الأمثل لبيئات تناول الطعام المكثفة والسريعة.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(43, 'Middleby Marshall', NULL, 'middleby-marshall', 'https://api.mariotstore.com/uploads/brands/middleby-marshall-logo.webp', '2026-03-09 07:39:12', '2026-05-23 20:23:20', 'Middleby Marshall is the undisputed world leader in commercial conveyor ovens. Their massive, high-speed impingement ovens are the absolute cornerstone of the global pizza delivery industry (including giants like Domino\'s and Papa John\'s), engineered to aggressively blast heat and bake hundreds of pizzas per hour with zero varying.', 'ميدلباي مارشال هي الشركة الرائدة عالميًا بلا منازع في أفران النقل التجارية. تعد أفرانها الضخمة عالية السرعة بمثابة حجر الزاوية المطلق لصناعة توصيل البيتزا العالمية (بما في ذلك الشركات العملاقة مثل Domino\'s و Papa John\'s)، والتي تم تصميمها لتفجير الحرارة بقوة وخبز مئات البيتزا في الساعة مع عدم تغير الصفر.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(44, 'miska', NULL, 'miska', 'https://api.mariotstore.com/uploads/brands/Logo-MiskaFoodTechnology1.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Miska Food Technology offers specialized heavy-duty processing solutions for demanding commercial environments. They build robust machinery aimed at simplifying bulk food preparation, providing durable planetary mixers and slicing solutions that reduce massive amounts of manual labor in busy cafeteria settings.', 'تقدم شركة Miska Food Technology حلول معالجة متخصصة للخدمة الشاقة للبيئات التجارية الصعبة. إنهم يبنون آلات قوية تهدف إلى تبسيط تحضير الطعام بكميات كبيرة، وتوفير خلاطات كوكبية متينة وحلول تقطيع تقلل من الكميات الهائلة من العمل اليدوي في إعدادات الكافتيريا المزدحمة.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(45, 'MKE-MATIC', NULL, 'mke-matic', 'https://api.mariotstore.com/uploads/brands/mke-logo.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'MKE is a highly dominant industrial kitchen brand hailing from Turkey, known for massive-scale capability. They operate enormous factories to produce everything from huge military-grade boiling kettles to expansive cold rooms, outfitting massive hotel infrastructures, hospitals, and industrial catering camps globally.', 'MKE هي علامة تجارية مهيمنة للغاية في مجال المطابخ الصناعية تنحدر من تركيا، ومعروفة بقدراتها واسعة النطاق. إنهم يديرون مصانع ضخمة لإنتاج كل شيء بدءًا من غلايات الغليان الضخمة ذات الجودة العسكرية إلى غرف التبريد الواسعة، وتجهيز البنية التحتية الضخمة للفنادق والمستشفيات ومعسكرات تقديم الطعام الصناعية على مستوى العالم.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(46, 'MOEL', NULL, 'moel', 'https://api.mariotstore.com/uploads/brands/moel.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Mo-El is a highly specialized Italian brand focusing entirely on professional hygiene and immediate heating solutions. They are most famous globally for their highly effective, specialized UV insect killers and powerful electric infrared heaters, which are heavily utilized in outdoor luxury dining patios and hygienic food processing plants.', 'Mo-El هي علامة تجارية إيطالية متخصصة للغاية تركز بالكامل على النظافة المهنية وحلول التدفئة الفورية. وهي مشهورة عالميًا بمبيدات الحشرات المتخصصة بالأشعة فوق البنفسجية والسخانات الكهربائية القوية التي تعمل بالأشعة تحت الحمراء، والتي يتم استخدامها بكثافة في أفنية تناول الطعام الفاخرة في الهواء الطلق ومصانع تجهيز الأغذية الصحية.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(47, 'MONOLITH', NULL, 'monolith', 'https://api.mariotstore.com/uploads/brands/monolith.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Monolith produces some of the most incredibly durable commercial plumbing fixtures in the industry. Their heavy-duty pre-rinse spray assemblies, specialized knee-operated sink valves, and massive commercial faucets are heavily over-engineered to withstand the absolute chaotic abuse of busy pot-washing stations.', 'تنتج شركة Monolith بعضًا من تركيبات السباكة التجارية الأكثر متانة في الصناعة. تم تصميم مجموعات الرش شديدة التحمل الخاصة بها قبل الشطف، وصمامات الحوض المتخصصة التي يتم تشغيلها بالركبة، والحنفيات التجارية الضخمة بشكل مفرط لتحمل سوء الاستخدام الفوضوي المطلق لمحطات غسيل الأواني المزدحمة.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(48, 'nuova SIMONELLI', NULL, 'nuova-simonelli', 'https://api.mariotstore.com/uploads/brands/simonelli.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Nuova Simonelli is an incredibly prestigious Italian company deeply embedded in the specialty coffee world, frequently serving as the highly esteemed official sponsor of the World Barista Championship. Their cutting-edge espresso machines are globally celebrated for their exceptional thermal stability, incredibly ergonomic barista-focused design, and advanced, scientific extraction technologies that push the boundaries of coffee flavor.', 'Nuova Simonelli هي شركة إيطالية مرموقة بشكل لا يصدق متجذرة بعمق في عالم القهوة المتخصصة، وكثيرًا ما تعمل كراعي رسمي محترم للغاية لبطولة باريستا العالمية. تحظى آلات الإسبريسو المتطورة الخاصة بها بشهرة عالمية بسبب ثباتها الحراري الاستثنائي، وتصميمها المريح الذي يركز على صانعي القهوة، وتقنيات الاستخلاص العلمية المتقدمة التي تدفع حدود نكهة القهوة.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(49, 'OMEGA', NULL, 'omega', 'https://api.mariotstore.com/uploads/brands/Omega.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Omega is a highly prestigious brand within the Minerva Omega group, representing the absolute pinnacle of Italian food processing mechanics. Their stunningly crafted gravity meat slicers, massive electric cheese graters, and industrial vacuums are legendary for their terrifyingly sharp precision and decades-long durability.', 'أوميغا هي علامة تجارية مرموقة للغاية ضمن مجموعة مينيرفا أوميغا، وتمثل القمة المطلقة لميكانيكا تصنيع الأغذية الإيطالية. تعتبر تقطيع اللحوم الجاذبية المصنوعة بشكل مذهل، ومبشرات الجبن الكهربائية الضخمة، والمكانس الصناعية أسطورية لدقتها الحادة المرعبة ومتانتها التي تدوم لعقود من الزمن.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(50, 'oztiryakiler', NULL, 'oztiryakiler', 'https://api.mariotstore.com/uploads/brands/oztriyakiler.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Oztiryakiler (often known as Ozti) is an absolute juggernaut in the commercial kitchen industry. Exporting from Turkey to over 100 countries, they manufacture a breathtakingly huge range of robust, heavy-duty equipment including massive combi ovens, flight dishwashers, and full modular cooking lines at highly competitive pricing.', 'Oztiryakiler (المعروف غالبًا باسم Ozti) هو الطاغوت المطلق في صناعة المطابخ التجارية. تقوم الشركة بالتصدير من تركيا إلى أكثر من 100 دولة، وتقوم بتصنيع مجموعة ضخمة بشكل مذهل من المعدات القوية والثقيلة بما في ذلك الأفران المجمعة الضخمة، وغسالات أطباق الطيران، وخطوط الطبخ المعيارية الكاملة بأسعار تنافسية للغاية.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(51, 'PITCO', NULL, 'pitco', 'https://api.mariotstore.com/uploads/brands/pitco.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'For over 100 years, Pitco has set the ultimate standard in commercial frying equipment engineering. Renowned for their bomb-proof robust construction and highly efficient tube-fired heating systems, Pitco fryers offer blisteringly rapid temperature recovery times. With advanced built-in oil filtration systems and massive output capacities, they easily handle the most demanding, high-volume kitchen environments on earth.', 'على مدار أكثر من 100 عام، وضعت شركة Pitco المعايير النهائية في هندسة معدات القلي التجارية. تشتهر مقالي بيتكو ببنيتها القوية المضادة للقنابل وأنظمة التسخين التي تعمل بالأنابيب ذات الكفاءة العالية، وتوفر أوقات استعادة درجة الحرارة بسرعة كبيرة. بفضل أنظمة ترشيح الزيت المدمجة المتقدمة وقدرات الإنتاج الهائلة، فإنها تتعامل بسهولة مع بيئات المطبخ ذات الحجم الكبير والأكثر تطلبًا على وجه الأرض.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(52, 'POSLIX', NULL, 'poslix', 'https://api.mariotstore.com/uploads/brands/poslix.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Poslix is a cutting-edge technology brand specializing entirely in advanced, highly responsive Point of Sale (POS) hardware. Their incredibly sleek, spill-resistant touchscreen terminals and rapid thermal receipt printers form the digital nervous system of modern, fast-paced restaurants and sprawling retail supermarkets.', 'Poslix هي علامة تجارية تكنولوجية متطورة متخصصة بالكامل في أجهزة نقاط البيع (POS) المتقدمة وعالية الاستجابة. تشكل شاشات اللمس الأنيقة والمقاومة للانسكاب وطابعات الإيصالات الحرارية السريعة الجهاز العصبي الرقمي للمطاعم الحديثة سريعة الخطى ومحلات السوبر ماركت المترامية الأطراف.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(53, 'PRINCE CASTLE', NULL, 'prince-castle', 'https://api.mariotstore.com/uploads/brands/prince-casle.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Prince Castle is a deeply historic American brand famous for heavily optimizing the fast-food workflow. They focus on holding, high-speed toasting, and precise portion control. Their vertical contact toasters and dedicated holding bins are actively used by the largest burger chains on earth to ensure immediate, hot food delivery.', 'تعد Prince Castle علامة تجارية أمريكية تاريخية للغاية وتشتهر بتحسين سير عمل الوجبات السريعة بشكل كبير. إنها تركز على الإمساك والتحميص عالي السرعة والتحكم الدقيق في الأجزاء. يتم استخدام المحامص العمودية وصناديق التخزين المخصصة بشكل نشط من قبل أكبر سلاسل البرجر على وجه الأرض لضمان توصيل الطعام الساخن الفوري.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(54, 'RANCILIO', NULL, 'rancilio', 'https://api.mariotstore.com/uploads/brands/Rancilio-logo-1.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Founded in 1927, Rancilio is a highly respected and historically significant Italian manufacturer of incredibly durable, consistent professional espresso machines and commercial flat-burr grinders. Their heavy-duty equipment is highly prized worldwide for its straightforward, bulletproof engineering, incredibly easy maintenance, and its unrelenting ability to produce excellent, traditional espresso shots year after demanding year.', 'تأسست شركة Rancilio عام 1927، وهي شركة تصنيع إيطالية تحظى باحترام كبير ولها أهمية تاريخية لآلات الإسبريسو الاحترافية المتينة والمتسقة والمطاحن التجارية ذات الشفرات المسطحة. تحظى معدات الخدمة الشاقة الخاصة بهم بتقدير كبير في جميع أنحاء العالم بسبب هندستها الواضحة والمضادة للرصاص، وسهولة الصيانة بشكل لا يصدق، وقدرتها التي لا هوادة فيها على إنتاج جرعات إسبرسو تقليدية ممتازة عامًا تلو الآخر.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL);
INSERT INTO `brands` (`id`, `name`, `name_ar`, `slug`, `image_url`, `created_at`, `updated_at`, `description`, `description_ar`, `website_url`, `is_active`, `priority`, `brand_type`, `banner_url`, `banner_url_mobile`, `image_url_ar`, `banner_url_ar`) VALUES
(55, 'RATIONAL', NULL, 'rational', 'https://api.mariotstore.com/uploads/brands/rational.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Rational is the undisputed, dominant world market leader in commercial combi-steam ovens and advanced intelligent cooking systems. Having invented the combi-steamer in 1976, their latest iCombi Pro ovens utilize highly advanced AI, responsive sensors, and precise climate management to automatically roast, bake, grill, and steam with perfect, reproducible precision, effectively replacing vast amounts of traditional, space-consuming kitchen equipment.', 'تعتبر شركة Rational الشركة الرائدة بلا منازع في السوق العالمية في مجال أفران البخار التجارية وأنظمة الطهي الذكية المتقدمة. بعد اختراع جهاز الطهي بالبخار المجمع في عام 1976، تستخدم أحدث أفران iCombi Pro الذكاء الاصطناعي المتقدم للغاية، وأجهزة استشعار سريعة الاستجابة، وإدارة دقيقة للمناخ للتحميص والخبز والشوي والتبخير تلقائيًا بدقة مثالية وقابلة للتكرار، لتحل بشكل فعال محل كميات هائلة من معدات المطبخ التقليدية التي تستهلك المساحة.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(57, 'robot coupe', NULL, 'robot-coupe', 'https://api.mariotstore.com/uploads/brands/robotcoupe.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'The prestigious French pioneer and true inventor of the food processor, Robot Coupe utterly leads the global industry in dynamic food preparation equipment. Their immensely powerful vegetable prep machines, robust bowl cutters, and heavy-duty stick blenders are found in virtually every professional kitchen on the planet, saving chefs countless hours of manual labor with their razor-sharp precision and unmatched motor torque.', 'الرائد الفرنسي المرموق والمخترع الحقيقي لمعالج الطعام، Robot Coupe يقود الصناعة العالمية في معدات إعداد الطعام الديناميكية. توجد آلات إعداد الخضار القوية للغاية، وقطاعات الأوعية القوية، والخلاطات اليدوية شديدة التحمل في كل مطبخ احترافي على هذا الكوكب تقريبًا، مما يوفر للطهاة ساعات لا حصر لها من العمل اليدوي بفضل دقتها الحادة وعزم دوران المحرك الذي لا مثيل له.', '', 1, NULL, 'All, Coffee & Bar', NULL, NULL, NULL, NULL),
(58, 'ROLLER GRILL', NULL, 'roller-grill', 'https://api.mariotstore.com/uploads/brands/roller-grill.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'As Europe\'s absolute leading manufacturer of specialized commercial cooking equipment, Roller Grill boasts the largest range of countertop machines in the world. Their crepe makers, heavy waffle irons, massive rotisseries, and hot dog rollers are engineered for non-stop, intense daily production in heavily trafficked kiosks and cafes.', 'باعتبارها الشركة المصنعة الرائدة على الإطلاق في أوروبا لمعدات الطبخ التجارية المتخصصة، تفتخر Roller Grill بأكبر مجموعة من الآلات التي توضع على سطح العمل في العالم. تم تصميم صانعي الكريب، ومكاوي الوافل الثقيلة، والمشويات الضخمة، وبكرات الهوت دوج لإنتاج يومي مكثف بدون توقف في الأكشاك والمقاهي التي يتم الاتجار بها بكثافة.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(59, 'ROTONDI', NULL, 'rotondi', 'https://api.mariotstore.com/uploads/brands/Rotondi-Group.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Rotondi Group is an incredibly high-tech Italian manufacturer specializing primarily in massive, industrial garment care and pressing machinery. While highly prevalent in commercial dry cleaning, their incredibly powerful steam generators and heavy-duty ironing boards are heavily utilized in huge 5-star hotel laundry operations.', 'Rotondi Group هي شركة تصنيع إيطالية ذات تقنية عالية بشكل لا يصدق متخصصة في المقام الأول في العناية بالملابس الصناعية الضخمة وآلات الضغط. على الرغم من انتشارها بشكل كبير في التنظيف الجاف التجاري، إلا أن مولدات البخار القوية بشكل لا يصدق وألواح الكي شديدة التحمل يتم استخدامها بشكل كبير في عمليات غسيل الملابس الضخمة في فنادق 5 نجوم.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(60, 'SAB', '', 'sab', 'https://api.mariotstore.com/uploads/brands/sab.webp', '2026-03-09 07:39:13', '2026-06-05 12:07:49', 'SAB Italia is a highly specialized artisan manufacturer of traditional espresso coffee machines. Handcrafted near Milan, SAB machines prioritize a deeply authentic, traditional mechanical aesthetic paired with incredibly heavy, highly thermally stable E61 brewing groups, delivering intensely rich, classic Italian espresso.', 'SAB Italia هي شركة تصنيع حرفية متخصصة للغاية في تصنيع آلات قهوة الإسبريسو التقليدية. تُعطي ماكينات SAB المصنوعة يدويًا بالقرب من ميلانو الأولوية للجماليات الميكانيكية التقليدية الأصيلة والمقترنة بمجموعات تخمير E61 ثقيلة بشكل لا يصدق ومستقرة حراريًا للغاية، مما يوفر إسبرسو إيطالي كلاسيكي غني بشكل مكثف.', '', 1, NULL, 'All', 'https://api.mariotstore.com/uploads/brands/1780661268941-106687854.webp', NULL, NULL, NULL),
(61, 'samixir', NULL, 'samixir', 'https://api.mariotstore.com/uploads/brands/samixir.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Samixir is a specialized Turkish manufacturer dominating the market for cold beverage dispensing. Their high-capacity stirred juice dispensers and incredibly chilling slush machines feature massive, indestructible bowls and aggressive cooling compressors, designed explicitly to thrive and perform in extreme summer heat environments.', 'Samixir هي شركة تصنيع تركية متخصصة تهيمن على سوق توزيع المشروبات الباردة. تتميز موزعات العصير المقلب ذات السعة العالية وآلات السلاش المبردة بشكل لا يصدق بأوعية ضخمة غير قابلة للتدمير وضواغط تبريد قوية، مصممة خصيصًا لتزدهر وتعمل في بيئات الصيف شديدة الحرارة.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(62, 'SANTOS', NULL, 'santos', 'https://api.mariotstore.com/uploads/brands/santos.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Santos is an incredibly prestigious French manufacturer with a 65-year history of building the world\'s finest commercial juicers and coffee grinders. Known for their whisper-quiet, incredibly high-torque induction motors, Santos machines are the absolute gold standard for high-end juice bars and luxury hotel breakfast buffets globally.', 'Santos هي شركة تصنيع فرنسية مرموقة بشكل لا يصدق ولها تاريخ يمتد إلى 65 عامًا في بناء أرقى العصائر ومطاحن القهوة التجارية في العالم. تشتهر ماكينات Santos بمحركاتها الحثية فائقة الهدوء وعزم الدوران العالي بشكل لا يصدق، وهي المعيار الذهبي المطلق لحانات العصائر الراقية وبوفيهات الإفطار في الفنادق الفاخرة على مستوى العالم.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(63, 'SAP', NULL, 'sap', 'https://api.mariotstore.com/uploads/brands/sap-bone-saw-machine-in-dubai.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'SAP is a highly specialized, heavy-industry Italian manufacturer of incredibly powerful meat processing machinery. Their massive stainless steel bone saws and huge commercial meat mincers are heavily relied upon by industrial slaughterhouses, massive fish markets, and extremely high-volume commercial butcheries.', 'SAP هي شركة تصنيع إيطالية متخصصة للغاية في مجال الصناعات الثقيلة لآلات معالجة اللحوم القوية بشكل لا يصدق. يتم الاعتماد بشكل كبير على مناشير العظام الضخمة المصنوعة من الفولاذ المقاوم للصدأ ومفارم اللحوم التجارية الضخمة من قبل المسالخ الصناعية وأسواق الأسماك الضخمة والمجازر التجارية ذات الحجم الكبير للغاية.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(64, 'SHEFFIELD', NULL, 'sheffield', 'https://api.mariotstore.com/uploads/brands/Sheffiel.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Sheffield provides robust, straightforward commercial refrigeration and heavy-duty food preparation equipment. Focusing heavily on exceptional value and unyielding reliability, Sheffield commercial freezers and preparation tables are highly popular choices for cost-conscious startups, busy food trucks, and medium-scale catering businesses.', 'توفر شيفيلد معدات تبريد تجارية قوية ومباشرة ومعدات إعداد الطعام شديدة التحمل. من خلال التركيز بشكل كبير على القيمة الاستثنائية والموثوقية التي لا تنضب، تعد المجمدات التجارية وطاولات التحضير من شيفيلد خيارات شائعة للغاية للشركات الناشئة التي تهتم بالتكلفة، وشاحنات الطعام المزدحمة، وشركات تقديم الطعام متوسطة الحجم.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(65, 'SOFINOR', NULL, 'sofinor', 'https://api.mariotstore.com/uploads/brands/sofinor.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Sofinor is a celebrated French manufacturer specializing heavily in the fabrication of premium stainless steel kitchen furniture and catering equipment. From highly specialized rotisseries to perfectly hygienic, knee-operated hand wash basins, Sofinor guarantees incredibly refined French engineering and flawless sanitary compliance.', 'Sofinor هي شركة تصنيع فرنسية مشهورة متخصصة بشكل كبير في تصنيع أثاث المطبخ ومعدات تقديم الطعام الفاخرة المصنوعة من الفولاذ المقاوم للصدأ. بدءًا من المشواة عالية التخصص وحتى أحواض غسيل الأيدي الصحية تمامًا والتي يتم تشغيلها بالركبة، تضمن سوفينور هندسة فرنسية راقية بشكل لا يصدق وامتثالًا صحيًا لا تشوبه شائبة.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(66, 'SOUTHBEND', NULL, 'southbend', 'https://api.mariotstore.com/uploads/brands/southbend.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Southbend is a deeply iconic, heavyweight American manufacturer of premium commercial cooking equipment. For over a century, their terrifyingly powerful blast-convection ovens, heavy-duty broilers, and massive cast-iron restaurant ranges have defined the high-volume, aggressive cooking environment of America\'s finest steakhouses.', 'Southbend هي شركة تصنيع أمريكية مميزة وثقيلة الوزن لمعدات الطبخ التجارية المتميزة. لأكثر من قرن من الزمان، حددت أفران الحمل الحراري القوية والمرعبة، والشوايات الثقيلة، ونطاقات المطاعم الضخمة المصنوعة من الحديد الزهر، بيئة الطهي العدوانية ذات الحجم الكبير لأرقى مطاعم شرائح اللحم في أمريكا.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(67, 'SPACEMAN', NULL, 'spaceman', 'https://api.mariotstore.com/uploads/brands/20210329_Spaceman-Logo_Black.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Spaceman is a highly innovative global leader in the manufacturing of incredibly powerful soft serve ice cream and frozen beverage machines. Their massive, dual-hopper machines utilize patented freezing cylinders to deliver insanely high hourly output of perfectly smooth ice cream, vastly outperforming extremely expensive competitors.', 'Spaceman هي شركة عالمية رائدة ومبتكرة للغاية في تصنيع آلات الآيس كريم والمشروبات المجمدة القوية بشكل لا يصدق. تستخدم أجهزتهم الضخمة ذات القادوس المزدوج أسطوانات التجميد الحاصلة على براءة اختراع لتقديم إنتاج عالي بشكل جنوني في الساعة من الآيس كريم السلس تمامًا، مما يتفوق بشكل كبير على المنافسين الباهظين للغاية.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(68, 'Speed Queen', NULL, 'speed-queen', 'https://api.mariotstore.com/uploads/brands/Speed-Queen.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Speed Queen is the undisputed, absolute legend of the commercial laundry industry. Manufactured in America, their massively over-engineered washing machines and huge tumble dryers are famous for lasting literally decades. They are the unbreakable, heavy-metal backbone of commercial laundromats and massive multi-housing facilities globally.', 'تعتبر Speed ​​Queen الأسطورة المطلقة بلا منازع في صناعة الغسيل التجاري. تم تصنيعها في أمريكا، وتشتهر غسالاتها ومجففاتها الضخمة التي تمت هندستها بشكل كبير بمدة بقائها لعقود من الزمن. إنها العمود الفقري غير القابل للكسر للمعادن الثقيلة للمغاسل التجارية والمرافق الضخمة متعددة المساكن على مستوى العالم.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(69, 'STAR', NULL, 'star', 'https://api.mariotstore.com/uploads/brands/star.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Star Manufacturing is a cornerstone American brand producing incredibly heavy-duty commercial cooking equipment. Their massive cast-iron griddles, terrifyingly fast conveyor toasters, and highly durable panini presses are the absolute, unbreakable foundation of busy 24/7 diners, delis, and high-volume sandwich chains.', 'Star Manufacturing هي علامة تجارية أمريكية أساسية تنتج معدات طهي تجارية شديدة التحمل بشكل لا يصدق. إن شبكاتها الضخمة المصنوعة من الحديد الزهر، ومحامص النقل السريعة بشكل مرعب، ومكابس البانيني المتينة للغاية هي الأساس المطلق وغير القابل للكسر لمطاعم الوجبات السريعة المزدحمة على مدار الساعة طوال أيام الأسبوع، وسلاسل الساندويتشات كبيرة الحجم.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(70, 'TOASTMASTER', NULL, 'toastmaster', 'https://api.mariotstore.com/uploads/brands/Toastmaster.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Toastmaster is a legendary, deeply historic brand that literally invented the pop-up toaster in the 1920s. Today, under the massive Middleby corporation, they manufacture highly rugged, heavy-duty countertop cooking equipment, including hot plates and griddles, built exactly to survive extremely punishing commercial environments.', 'Toastmaster هي علامة تجارية أسطورية وتاريخية للغاية اخترعت حرفيًا محمصة الخبز المنبثقة في عشرينيات القرن الماضي. اليوم، في إطار شركة ميدلباي الضخمة، يقومون بتصنيع معدات طهي عالية التحمل وشديدة التحمل، بما في ذلك ألواح التسخين والشوايات، المصممة خصيصًا للبقاء على قيد الحياة في البيئات التجارية القاسية للغاية.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(71, 'UNION', NULL, 'union', 'https://api.mariotstore.com/uploads/brands/Union.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Union is an Italian industrial juggernaut and the absolute global leader in the highly complex dry cleaning machinery sector. Their incredibly massive, highly advanced dry cleaning plants utilize complex, computerized solvent recovery systems, making them an absolute necessity for enormous, industrial-scale high-end garment care operations.', 'Union هي شركة صناعية إيطالية عملاقة والرائدة عالميًا في قطاع آلات التنظيف الجاف شديد التعقيد. تستخدم مصانع التنظيف الجاف الضخمة والمتقدمة للغاية الخاصة بها أنظمة معقدة ومحوسبة لاستعادة المذيبات، مما يجعلها ضرورة مطلقة لعمليات العناية بالملابس الراقية الضخمة على نطاق صناعي.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(72, 'VULCAN', NULL, 'vulcan', 'https://api.mariotstore.com/uploads/brands/VULCAN-BRAND.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Vulcan is a deeply historic, premier American manufacturer of heavy-duty, ultra-reliable commercial cooking equipment. Known for uncompromising master craftsmanship and raw power, their extensive line includes robust cast-iron gas ranges, high-capacity griddles, convection ovens, and massive steam kettles, providing the hot, beating heart required by countless, high-volume restaurant and institutional kitchens.', 'فولكان هي شركة تصنيع أمريكية رائدة وتاريخية للغاية لمعدات الطبخ التجارية شديدة التحمل والموثوقة للغاية. تشتهر بمهارة الصنعة الفائقة والقوة الخام، ويشمل خطها الواسع نطاقات غاز قوية من الحديد الزهر، وشوايات عالية السعة، وأفران حرارية، وغلايات بخار ضخمة، مما يوفر القلب الساخن النابض الذي يتطلبه عدد لا يحصى من المطاعم والمطابخ المؤسسية ذات الحجم الكبير.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(73, 'SERVER', NULL, 'server', 'https://api.mariotstore.com/uploads/brands/server.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Server Products is a highly specialized American manufacturer dominating the condiment and portion-control dispensing market. Their heavy-duty, stainless steel pump dispensers and specialized food warmers ensure exact, measured portions of hot fudge, cheese, and sauces, heavily optimizing food costs for massive global fast-food chains.', 'تعد شركة Server Products شركة تصنيع أمريكية متخصصة للغاية تهيمن على سوق توزيع البهارات والتحكم في الأجزاء. تضمن موزعات المضخات المصنوعة من الفولاذ المقاوم للصدأ شديدة التحمل وسخانات الطعام المتخصصة الحصول على كميات دقيقة ومحسوبة من الحلوى الساخنة والجبن والصلصات، مما يؤدي إلى تحسين تكاليف الطعام بشكل كبير لسلاسل الوجبات السريعة العالمية الضخمة.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(74, 'STILCO', NULL, 'stilco', 'https://api.mariotstore.com/uploads/brands/stilco1.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Stilco provides incredibly rugged, no-nonsense commercial catering equipment designed for heavy, practical utility. Their specialized shawarma machines, huge electric fryers, and high-capacity food warmers are incredibly popular among fast-food kiosks and massive cafeterias that demand absolute reliability under constant abuse.', 'توفر Stilco معدات تقديم الطعام التجارية القوية بشكل لا يصدق والمصممة للاستخدام الثقيل والعملي. تحظى آلات الشاورما المتخصصة، والمقالي الكهربائية الضخمة، وسخانات الطعام عالية السعة بشعبية كبيرة بين أكشاك الوجبات السريعة والكافيتريات الضخمة التي تتطلب الموثوقية المطلقة في ظل سوء الاستخدام المستمر.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(75, 'TECHNOCOOLER', NULL, 'technocooler', 'https://api.mariotstore.com/uploads/brands/technocooler.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Technocooler specializes entirely in highly advanced commercial refrigeration and huge cold storage solutions. Utilizing incredibly efficient compressors and deep polyurethane insulation, they manufacture massive chilled display cabinets and deep freezers that are critical for preserving vast amounts of inventory in supermarkets and massive dark kitchens.', 'تتخصص شركة Technocooler بالكامل في مجال التبريد التجاري المتقدم للغاية وحلول التخزين البارد الضخمة. باستخدام ضواغط فعالة بشكل لا يصدق وعزل عميق من مادة البولي يوريثين، يقومون بتصنيع خزائن عرض مبردة ضخمة ومجمدات عميقة تعتبر ضرورية للحفاظ على كميات هائلة من المخزون في محلات السوبر ماركت والمطابخ المظلمة الضخمة.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(76, 'TECNODOM', NULL, 'tecnodom', 'https://api.mariotstore.com/uploads/brands/tecnodom.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Tecnodom is an enormous Italian manufacturing giant producing incredibly massive quantities of commercial refrigeration and stainless steel equipment. They offer exceptional European build qualityâ€”manufacturing specialized pizza prep counters, huge blast chillers, and massive upright freezersâ€”at incredibly aggressive, highly competitive global price points.', 'Tecnodom هي شركة تصنيع إيطالية عملاقة تنتج كميات هائلة بشكل لا يصدق من أجهزة التبريد التجارية ومعدات الفولاذ المقاوم للصدأ. إنها توفر جودة بناء أوروبية استثنائية - حيث تقوم بتصنيع طاولات إعداد البيتزا المتخصصة، ومبردات الانفجار الضخمة، والمجمدات العمودية الضخمة - بنقاط أسعار عالمية عدوانية للغاية وتنافسية للغاية.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(77, 'UEBERMILK', NULL, 'uebermilk', 'https://api.mariotstore.com/uploads/brands/uebermilk_logo_small.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Ubermilk is a highly advanced, ultra-innovative German brand that completely solved the biggest bottleneck in specialty coffee: milk frothing. Their incredibly advanced, automated milk frothers perfectly steam and texture hundreds of liters of milk per hour with zero varying, allowing baristas to focus entirely on espresso extraction and customer service.', 'Ubermilk هي علامة تجارية ألمانية متقدمة للغاية ومبتكرة للغاية، وقد نجحت في حل أكبر مشكلة في مجال القهوة المتخصصة: رغوة الحليب. تعمل أجهزة صنع رغوة الحليب الأوتوماتيكية المتقدمة بشكل لا يصدق على تبخير مئات اللترات من الحليب في الساعة وتكوينها بشكل مثالي دون أي تغيير، مما يسمح لخبراء صناعة القهوة بالتركيز بشكل كامل على استخلاص الإسبريسو وخدمة العملاء.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(78, 'UNOX', NULL, 'unox', 'https://api.mariotstore.com/uploads/brands/unox.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Unox is renowned globally for engineering highly innovative, intelligent, and technologically advanced commercial baking and gastronomy combi ovens. Driven heavily by data science and IoT connectivity, Unox ovens deliver masterfully precise humidity control, dynamic bi-directional air circulation, and perfectly even cooking results, empowering large-scale bakeries and elite restaurants to scale their menus flawlessly.', 'تشتهر شركة Unox عالميًا بهندسة أفران الخبز التجارية وفن الطهي المبتكرة للغاية والذكية والمتقدمة تقنيًا. بفضل علوم البيانات والاتصال بإنترنت الأشياء، توفر أفران Unox تحكمًا دقيقًا في الرطوبة، ودوران هواء ديناميكي ثنائي الاتجاه، ونتائج طهي متساوية تمامًا، مما يمكّن المخابز واسعة النطاق ومطاعم النخبة من توسيع نطاق قوائمها بشكل لا تشوبه شائبة.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(79, 'VITAMIX', NULL, 'vitamix', 'https://api.mariotstore.com/uploads/brands/vitamix.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Vitamix Commercial remains the ultimate, unrivaled choice for high-end, professional blending. Known for their unmatched, ultra-high-horsepower motors, custom-designed aircraft-grade stainless steel blades, and legendary durability, they can completely pulverize whole ingredients into the smoothest purees, hot soups, and frozen beverages, making them indispensable workhorses in fine dining kitchens and specialized cocktail bars.', 'يبقى Vitamix Commercial الخيار الأمثل الذي لا مثيل له للمزج الاحترافي الراقي. تشتهر بمحركاتها التي لا مثيل لها ذات القدرة الحصانية العالية، والشفرات المصنوعة من الفولاذ المقاوم للصدأ المصممة خصيصًا للطائرات، والمتانة الأسطورية، ويمكنها سحق المكونات بالكامل بالكامل وتحويلها إلى أنعم الأطعمة المهروسة والحساء الساخن والمشروبات المجمدة، مما يجعلها أدوات عمل لا غنى عنها في مطابخ الطعام الفاخرة وبارات الكوكتيل المتخصصة.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(80, 'BATTISTELLA', '', 'battistella', 'https://api.mariotstore.com/uploads/brands/BATTISTELLA-1.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Battistella is a highly specialized Italian manufacturer dominating the professional wet cleaning and heavy ironing sector. Their incredibly powerful, high-pressure industrial steam generators and massive, heated vacuum ironing boards are completely essential for high-end boutique dry cleaners and massive 5-star hotel luxury garment care.', 'باتيستيلا هي شركة تصنيع إيطالية متخصصة للغاية تهيمن على قطاع التنظيف الرطب والكي الثقيل. تعد مولدات البخار الصناعية ذات الضغط العالي القوية بشكل لا يصدق وألواح الكي الضخمة والمدفأة ضرورية تمامًا للتنظيف الجاف في البوتيكات الراقية والعناية بالملابس الفاخرة في فندق 5 نجوم.', '', 1, NULL, 'All', '', NULL, NULL, NULL),
(81, 'BILAIT', '', 'bilait', 'https://api.mariotstore.com/uploads/brands/BILAIT-Logo.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Bilait specializes incredibly heavily in producing professional-grade, high-volume chocolate and specialized confectionery equipment. Their highly advanced tempering machines and massive hot chocolate dispensers feature incredibly precise, constant temperature control, ensuring massive amounts of chocolate perfectly retain their gloss, snap, and crystalline structure.', 'تتخصص شركة بيليت بشكل كبير في إنتاج الشوكولاتة الاحترافية بكميات كبيرة ومعدات الحلويات المتخصصة. تتميز آلات التقسية المتقدمة للغاية وموزعات الشوكولاتة الساخنة الضخمة بدقة لا تصدق وتحكم ثابت في درجة الحرارة، مما يضمن احتفاظ كميات هائلة من الشوكولاتة بشكل مثالي بلمعانها وبنيتها البلورية.', '', 1, NULL, 'All', '', NULL, NULL, NULL),
(82, 'VITO', NULL, 'vito', 'https://api.mariotstore.com/uploads/brands/VITO-OIL-FILTER-SYSTEM.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Vito is a revolutionary German manufacturer that radically changed commercial frying. Their highly advanced, drop-in oil filtration systems aggressively suck up and micro-filter frying oil directly in the hot vat. By massively clearing out microscopic carbon, Vito systems drastically double the life of expensive cooking oil, saving massive restaurants absolute fortunes.', 'فيتو هي شركة تصنيع ألمانية ثورية قامت بتغيير القلي التجاري بشكل جذري. تعمل أنظمة ترشيح الزيت المتطورة للغاية على امتصاص زيت القلي وتصفيته بشكل دقيق مباشرة في الوعاء الساخن. من خلال إزالة الكربون المجهري على نطاق واسع، تعمل أنظمة Vito على مضاعفة عمر زيت الطهي باهظ الثمن بشكل كبير، مما يوفر ثروات كبيرة للمطاعم الضخمة.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(84, 'Zumex', NULL, 'zumex', 'https://api.mariotstore.com/uploads/brands/Zumex.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'With over 35 years of dedicated innovation, Zumex is the global frontrunner in the design and manufacturing of beautiful, automatic commercial citrus juicers. Their deeply iconic and highly visual squeezing systems are uniquely engineered to extract maximum juice yield without ever crushing the bitter rind, consistently providing the freshest, sweetest, highest-quality juice for luxury hotels, premium supermarkets, and health-focused juice bars.', 'مع أكثر من 35 عامًا من الابتكار المتفاني، تعد Zumex الشركة الرائدة عالميًا في تصميم وتصنيع عصارات الحمضيات التجارية الأوتوماتيكية الجميلة. تم تصميم أنظمة الضغط المميزة والبصرية للغاية بشكل فريد لاستخراج أقصى قدر من إنتاج العصير دون سحق القشرة المرة، مما يوفر باستمرار العصير الطازج والحلاوة والأعلى جودة للفنادق الفاخرة ومحلات السوبر ماركت المتميزة وألواح العصير التي تركز على الصحة.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(85, 'Ailipu', '', 'ailipu', 'https://api.mariotstore.com/uploads/brands/ailipu-1.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Ailipu is a highly specialized manufacturer focusing incredibly heavily on advanced, high-power commercial induction cooking technologies. Their massive commercial induction hobs and huge electric wok cookers provide terrifyingly fast, deeply intensive heat transfer, replacing massive, dangerous gas installations in modern, high-tech commercial kitchens.', '', '', 1, 4, 'All', '', '', NULL, NULL),
(86, 'Bimatic', '', 'bimatic', 'https://api.mariotstore.com/uploads/brands/bimatic.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Bimatic is an incredibly respected Italian manufacturer specializing entirely in the complex edge-banding and specialized woodworking machinery sector. Within the hospitality space, their massive, highly precise machinery is utilized globally to construct completely flawless, incredibly durable commercial bar counters, massive hotel reception desks, and robust kitchen cabinetry.', 'Bimatic هي شركة تصنيع إيطالية تحظى باحترام كبير وتتخصص بالكامل في قطاع آلات الأعمال الخشبية المتخصصة ونطاقات الحواف المعقدة. وفي مجال الضيافة، يتم استخدام آلاتهم الضخمة عالية الدقة على مستوى العالم لبناء طاولات بار تجارية متينة بشكل لا يصدق، ومكاتب استقبال فندقية ضخمة، وخزائن مطبخ قوية.', '', 1, 3, 'All', '', '', NULL, NULL),
(87, 'Bunn', '', 'bunn', 'https://api.mariotstore.com/uploads/brands/bunn.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Bunn-O-Matic is an absolute, legendary titan of the American coffee industry. Having invented the flat-bottom coffee filter, Bunn today manufactures incredibly advanced, indestructible high-volume batch brewers and massive hot water towers. They are the absolute, unquestioned backbone of hot beverage delivery for global diners, massive chain restaurants, and huge hotels.', 'Bunn-O-Matic هو عملاق أسطوري في صناعة القهوة الأمريكية. بعد أن اخترعت فلتر القهوة ذو القاعدة المسطحة، تقوم شركة Bunn اليوم بتصنيع آلات تحضير القهوة ذات الحجم الكبير المتقدمة وغير القابلة للتدمير وأبراج المياه الساخنة الضخمة. إنهم العمود الفقري المطلق الذي لا جدال فيه لتوصيل المشروبات الساخنة للمطاعم العالمية وسلاسل المطاعم الضخمة والفنادق الضخمة.', '', 1, NULL, 'All', '', NULL, NULL, NULL),
(88, 'Grindmaster', '', 'grindmaster', 'https://api.mariotstore.com/uploads/brands/grindmaster.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Grindmaster (now Grindmaster-Cecilware) is a deeply historic American manufacturer with absolute mastery over commercial beverage dispensing. They produce incredibly massive, high-volume coffee grinders, huge hot water urns, and terrifyingly efficient cold beverage bubblers, designed specifically to operate continuously in extremely high-traffic massive cafeterias.', 'Grindmaster (المعروفة الآن باسم Grindmaster-Cecilware) هي شركة تصنيع أمريكية ذات تاريخ عميق تتمتع بإتقان مطلق في توزيع المشروبات التجارية. إنهم ينتجون مطاحن قهوة كبيرة الحجم وضخمة بشكل لا يصدق، وجرارًا ضخمة للمياه الساخنة، وفقاعات مشروبات باردة ذات كفاءة مرعبة، مصممة خصيصًا للعمل بشكل مستمر في الكافيتريات الضخمة ذات حركة المرور العالية للغاية.', '', 1, NULL, 'All', '', NULL, NULL, NULL),
(89, 'Hoshizaki', '', 'hoshizaki', 'https://api.mariotstore.com/uploads/brands/hoshizaki.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Hoshizaki is a legendary, massive Japanese corporation and generally considered the absolute pinnacle of commercial ice-making engineering globally. Known for their terrifying precision, Hoshizaki machines employ an incredibly unique, massive closed-cell water system to produce absolutely flawless, incredibly hard, perfectly pure ice cubes that simply refuse to melt quickly.', '\"هوشيزاكي\" هي شركة يابانية ضخمة وأسطورية، وتُعتبر عمومًا القمة المطلقة لهندسة صناعة الثلج التجاري على مستوى العالم. تستخدم آلات هوشيزاكي، المعروفة بدقتها المرعبة، نظامًا مائيًا ضخمًا وفريدًا من نوعه من الخلايا المغلقة لإنتاج مكعبات ثلج خالية تمامًا من العيوب وصلبة بشكل لا يصدق ونقية تمامًا والتي ببساطة ترفض الذوبان بسرعة.', '', 1, NULL, 'All', '', NULL, NULL, NULL),
(90, 'Mussana', NULL, 'mussana', 'https://api.mariotstore.com/uploads/brands/mussana.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Mussana is a highly specialized German manufacturer widely considered to build the absolute greatest cream whipping machines on planet earth. Using an incredibly advanced, highly guarded internal micro-labyrinth system, Mussana machines transform liquid cream into an incredibly dense, extremely voluminous structure impossible to achieve by hand or blender.', 'Mussana هي شركة تصنيع ألمانية متخصصة للغاية ويُنظر إليها على نطاق واسع على أنها تصنع أعظم آلات خفق الكريمة على كوكب الأرض. باستخدام نظام متاهة داخلية دقيقة متطور بشكل لا يصدق، يخضع لحراسة مشددة، تقوم آلات Mussana بتحويل الكريمة السائلة إلى بنية كثيفة للغاية وضخمة للغاية يستحيل تحقيقها باليد أو الخلاط.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(91, 'Pastaline', NULL, 'pastaline', 'https://api.mariotstore.com/uploads/brands/pastaline.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Pastaline is an incredibly specialized Italian manufacturer completely dedicated to the ancient art of dough processing. Their massive, highly advanced dough sheeters, extremely aggressive spiral mixers, and specialized pasta extruders bring absolute, unquestioned industrial efficiency to the deeply traditional creation of fresh, authentic Italian pasta and massive pizzas.', 'باستالاين هي شركة تصنيع إيطالية متخصصة بشكل لا يصدق ومكرسة بالكامل للفن القديم لمعالجة العجين. إن صفائح العجين الضخمة والمتقدمة للغاية، والخلاطات الحلزونية القوية للغاية، وأجهزة بثق المعكرونة المتخصصة تجلب كفاءة صناعية مطلقة لا جدال فيها إلى الإبداع التقليدي العميق للمعكرونة الإيطالية الطازجة والأصيلة والبيتزا الضخمة.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(92, 'Salva', NULL, 'salva', 'https://api.mariotstore.com/uploads/brands/salva.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Salva is a massive, highly prestigious Spanish manufacturer of incredibly advanced, heavy-duty commercial bakery equipment. Their enormous rotary rack ovens, deeply insulated modular deck ovens, and heavy volumetric dough dividers are universally trusted by massive industrial bakeries and large supermarkets globally to continuously produce flawless, artisanal breads.', 'تعتبر شركة Salva شركة تصنيع إسبانية ضخمة ومرموقة للغاية لمعدات المخابز التجارية شديدة التحمل والمتقدمة بشكل لا يصدق. إن أفران الرف الدوارة الضخمة، وأفران السطح المعيارية المعزولة بعمق، وفواصل العجين ذات الحجم الثقيل تحظى بثقة عالمية من قبل المخابز الصناعية الضخمة ومحلات السوبر ماركت الكبيرة على مستوى العالم لإنتاج الخبز الحرفي الخالي من العيوب بشكل مستمر.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(93, 'Snooker', NULL, 'snooker', 'https://api.mariotstore.com/uploads/brands/snooker-1.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Snooker specializes incredibly heavily in producing highly cost-effective, extremely rugged commercial ice making machines. Highly popular strongly across the massive Asian and Middle Eastern markets, Snooker provides incredibly reliable, heavy-duty ice production for very busy restaurants, large juice bars, and massive fish displays at highly competitive price points.', 'تتخصص شركة Snooker بشكل كبير في إنتاج آلات صنع الثلج التجارية ذات الفعالية العالية من حيث التكلفة والقوة العالية. تحظى شركة Snooker بشعبية كبيرة في أسواق آسيا والشرق الأوسط الضخمة، وتوفر إنتاجًا موثوقًا به للثلج عالي التحمل للمطاعم المزدحمة جدًا، وحانات العصائر الكبيرة، وعروض الأسماك الضخمة بأسعار تنافسية للغاية.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(94, 'Turbo Chef', NULL, 'turbo-chef', 'https://api.mariotstore.com/uploads/brands/turbo-chef.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'TurboChef (a massive Middleby brand) completely invented and dominates the absolute pinnacle of the rapid-cook oven industry. Using terrifyingly advanced microwaves and incredibly aggressive jets of super-heated impinged air, TurboChef ovens can literally cook a completely raw pizza or deeply toast a sandwich perfectly in a shocking 60 seconds.', 'لقد اخترعت TurboChef (علامة تجارية ضخمة من Middleby) وتهيمن على القمة المطلقة لصناعة أفران الطهي السريع. باستخدام أفران ميكروويف متقدمة بشكل مرعب ونفاثات قوية بشكل لا يصدق من الهواء المندفع فائق السخونة، يمكن لأفران TurboChef طهي بيتزا خام تمامًا أو تحميص شطيرة بعمق بشكل مثالي في 60 ثانية مذهلة.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(95, 'Venarro', NULL, 'venarro', 'https://api.mariotstore.com/uploads/brands/venarro.webp', '2026-03-09 07:39:13', '2026-05-23 20:23:20', 'Venarro is a highly aggressive, rapidly expanding manufacturer of heavy-duty commercial kitchen equipment. Based heavily in Turkey, Venarro produces incredibly durable, massive industrial cooking ranges, huge convection ovens, and exceptionally robust stainless steel handling equipment designed to easily survive the incredible abuse of massive industrial catering.', 'تعد شركة Venarro شركة مصنعة قوية للغاية وسريعة التوسع لمعدات المطبخ التجارية شديدة التحمل. مقرها الرئيسي في تركيا، تنتج شركة Venarro نطاقات طهي صناعية ضخمة ومتينة بشكل لا يصدق، وأفران حرارية ضخمة، ومعدات مناولة قوية بشكل استثنائي مصنوعة من الفولاذ المقاوم للصدأ مصممة لتنجو بسهولة من سوء الاستخدام المذهل لخدمات تقديم الطعام الصناعية الضخمة.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(96, 'Venix', 'فينيكس', 'venix', 'https://api.mariotstore.com/uploads/brands/venix.webp', '2026-06-01 13:02:26', '2026-06-01 13:02:26', 'Venix is a deeply innovative, highly advanced Italian manufacturer specializing entirely in high-tech commercial ovens and massive blast chillers. Driven incredibly heavily by smart, touchscreen technology and elegant Italian design, Venix combi-ovens deliver perfectly precise humidity and aggressive heat control for sophisticated hotel banqueting and massive bakeries.', 'فينيكس هي شركة تصنيع إيطالية مبتكرة ومتقدمة للغاية تتخصص بالكامل في الأفران التجارية عالية التقنية والمبردات السريعة الضخمة. تعتمد أفران فينيكس بشكل كبير على التقنية الذكية بشاشات اللمس والتصميم الإيطالي الأنيق، وتوفر تحكمًا دقيقًا للغاية في الرطوبة والحرارة القوية لتلبية احتياجات حفلات الفنادق الراقية والمخابز الضخمة.', NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
(123, 'FAGORPROFESIONAL', NULL, 'fagorprofesional', 'https://api.mariotstore.com/uploads/brands/FagorProfesional.webp', '2026-06-01 15:56:15', '2026-06-01 15:56:15', NULL, NULL, NULL, 1, NULL, 'All', NULL, NULL, NULL, NULL),
