(1, 'Coffee Makers', 'coffee-makers', 'https://api.mariotstore.com/uploads/1780139249336-61074613.webp', '', 'Brew the perfect cup every time with our professional-grade coffee making equipment.', 'قم بتحضير الكوب المثالي في كل مرة باستخدام معدات صنع القهوة الاحترافية لدينا.', '2026-04-09 15:28:12', '2026-05-30 11:07:33', 1, NULL, 'main_category', 'Anfim, LA MARZOCCO, LA CIMBALI, RANCILIO, SAB, Bunn, Grindmaster', 'ماكينات صنع القهوة', 0, 3, NULL, NULL, 0, NULL, NULL),
(2, 'Espresso Machines', 'espresso-machines', 'https://api.mariotstore.com/uploads/1780127166342-112662457.webp', '', 'Extract rich, flavorful espresso shots with precision using our top-tier machines.', 'استخلص جرعات إسبريسو غنية ولذيذة بدقة باستخدام أجهزتنا عالية الجودة.', '2026-04-09 15:28:12', '2026-05-30 07:46:07', 1, 1, 'sub_category', '', 'ماكينات إسبريسو', 0, 1, NULL, NULL, 0, NULL, NULL),
(3, 'Volumetric Espresso Machines', 'volumetric-espresso-machines', NULL, NULL, 'Achieve consistent extraction volumes automatically for high-paced cafe environments.', 'حقق أحجام استخلاص متسقة تلقائيًا لبيئات المقاهي سريعة الوتيرة.', '2026-04-09 15:28:12', '2026-05-30 06:46:54', 1, 2, 'sub_sub_category', NULL, 'ماكينات إسبريسو حجمية', 0, 0, NULL, NULL, 0, NULL, NULL),
(4, 'Gravimetric Espresso Machines', 'gravimetric-espresso-machines', NULL, NULL, 'Control your espresso output by weight for unparalleled consistency and flavor profiles.', 'تحكم في إنتاج الإسبريسو بالوزن للحصول على تناسق ونكهات لا مثيل لها.', '2026-04-09 15:28:12', '2026-05-30 06:46:54', 1, 2, 'sub_sub_category', NULL, 'ماكينات إسبريسو وزنية', 0, 0, NULL, NULL, 0, NULL, NULL),
(5, 'Coffee Grinders', 'coffee-grinders', 'https://api.mariotstore.com/uploads/1780127152956-712556866.webp', '', 'Ensure a uniform grind size to unlock the true aroma of your coffee beans.', 'تأكد من حجم طحن موحد لإطلاق الرائحة الحقيقية لحبوب القهوة الخاصة بك.', '2026-04-09 15:28:12', '2026-05-30 07:45:55', 1, 1, 'sub_category', '', 'مطاحن القهوة', 0, 2, NULL, NULL, 0, NULL, NULL),
(6, 'Espresso Grinders', 'espresso-grinders', NULL, NULL, 'Fine-tune your espresso grind with our specialized micro-adjustable burr grinders.', 'اضبط طحن الإسبريسو الخاص بك من خلال مطاحننا المتخصصة القابلة للتعديل الدقيق.', '2026-04-09 15:28:12', '2026-05-30 06:46:54', 1, 5, 'sub_sub_category', NULL, 'مطاحن إسبريسو', 0, 0, NULL, NULL, 0, NULL, NULL),
(7, 'Brewed Coffee Grinders', 'brewed-coffee-grinders', NULL, NULL, 'Get the ideal coarse or medium grind for filter, drip, and French press coffee.', 'احصل على الطحن الخشن أو المتوسط ​​المثالي للقهوة المفلترة والمقطرة والفرنش بريس.', '2026-04-09 15:28:12', '2026-05-30 06:46:54', 1, 5, 'sub_sub_category', NULL, 'مطاحن القهوة المقطرة', 0, 0, NULL, NULL, 0, NULL, NULL),
(8, 'Coffee & Tea Brewers', 'coffee-and-tea-brewers', 'https://api.mariotstore.com/uploads/1780127141026-521695058.webp', '', 'Serve large volumes of freshly brewed coffee and hot tea efficiently.', 'قدم كميات كبيرة من القهوة الطازجة والشاي الساخن بكفاءة عالية.', '2026-04-09 15:28:12', '2026-05-30 07:45:42', 1, 1, 'sub_category', '', 'محضرات القهوة والشاي', 0, 3, NULL, NULL, 0, NULL, NULL),
(9, 'Pour Overs', 'pour-overs', NULL, NULL, 'Master the art of manual brewing with our specialized pour-over accessories and kettles.', 'أتقن فن التخمير اليدوي باستخدام ملحقات وغلايات التقطير المتخصصة لدينا.', '2026-04-09 15:28:12', '2026-05-30 06:46:54', 1, 8, 'sub_sub_category', NULL, 'أدوات التقطير', 0, 0, NULL, NULL, 0, NULL, NULL),
(10, 'Water Boilers', 'water-boilers', NULL, NULL, 'Maintain hot water at the exact temperature needed for tea and instant beverages.', 'حافظ على الماء الساخن في درجة الحرارة الدقيقة المطلوبة للشاي والمشروبات السريعة.', '2026-04-09 15:28:12', '2026-05-30 06:46:54', 1, 8, 'sub_sub_category', NULL, 'غلايات المياه', 0, 0, NULL, NULL, 0, NULL, NULL),
(11, 'Filters', 'filters', '', NULL, 'High-quality paper and metal filters to guarantee a clean and sediment-free brew.', 'فلاتر ورقية ومعدنية عالية الجودة لضمان مشروب نقي وخالٍ من الرواسب.', '2026-04-09 15:28:12', '2026-05-30 06:46:54', 1, 8, 'sub_sub_category', '', 'فلاتر', 0, 0, NULL, NULL, 0, NULL, NULL),
(12, 'Tea Makers', 'tea-makers', NULL, NULL, 'Steep your loose leaf and bagged teas perfectly with our dedicated tea equipment.', 'قم بتخمير الشاي السائب وأكياس الشاي بشكل مثالي باستخدام معدات الشاي المخصصة لدينا.', '2026-04-09 15:28:12', '2026-05-30 06:46:54', 1, 8, 'sub_sub_category', NULL, 'صناع الشاي', 0, 0, NULL, NULL, 0, NULL, NULL),
(13, 'Ice equipment', 'ice-equipment', 'https://api.mariotstore.com/uploads/1780139846619-710421440.webp', '', 'Keep your drinks perfectly chilled with our high-capacity commercial ice solutions.', 'حافظ على مشروباتك مبردة تمامًا من خلال حلول الثلج التجارية عالية السعة.', '2026-04-09 15:28:12', '2026-05-30 11:17:31', 1, NULL, 'main_category', 'BREMA, Hoshizaki, Snooker', 'معدات الثلج', 0, 0, NULL, NULL, 0, NULL, NULL),
(14, 'Ice Cube', 'ice-cube', NULL, NULL, 'Produce crystal-clear, slow-melting ice cubes ideal for premium cocktails and sodas.', 'أنتج مكعبات ثلج صافية وبطيئة الذوبان مثالية للكوكتيلات والمشروبات الغازية الفاخرة.', '2026-04-09 15:28:12', '2026-05-30 06:46:54', 1, 13, 'sub_category', NULL, 'مكعبات ثلج', 0, 0, NULL, NULL, 0, NULL, NULL),
(15, 'Ice Flakers', 'ice-flakers', NULL, NULL, 'Generate soft, moldable flaked ice perfect for food displays and healthcare use.', 'قم بتوليد ثلج قشري ناعم وقابل للتشكيل مثالي لعروض الطعام واستخدامات الرعاية الصحية.', '2026-04-09 15:28:12', '2026-05-30 06:46:54', 1, 13, 'sub_category', NULL, 'قشور ثلج', 0, 0, NULL, NULL, 0, NULL, NULL),
(16, 'Ice Bin', 'ice-bin', NULL, NULL, 'Store large quantities of ice hygienically with our insulated storage bins.', 'قم بتخزين كميات كبيرة من الثلج بشكل صحي باستخدام صناديق التخزين المعزولة لدينا.', '2026-04-09 15:28:12', '2026-05-30 06:46:54', 1, 13, 'sub_category', NULL, 'حاويات ثلج', 0, 0, NULL, NULL, 0, NULL, NULL),
