]', 2970.00, 0.00, 148.50, 3118.50, '2026-06-20 17:20:15'),
(14, 'EQT-00014', 1, 'Admin Jamal', 'Mohamadjadoue@gmail.com', '0569672393', '', '[{\"id\":60,\"variant_id\":null,\"name\":\"Work Table with Backsplash, Left, Right Side Splash, Middle and Bottom Shelf\",\"name_ar\":\"طاولة عمل مزودة بحافة خلفية، وحافة جانبية يمنى ويسرى، ورف أوسط وسفلي\",\"slug\":\"work-table-with-backsplash,-left,-right-side-splash,-middle-and-bottom-shelf\",\"price\":990,\"image\":\"https://api.mariotstore.com/uploads/1781772692983-565026011.webp\",\"brand\":\"MARIOT FABRICATION\",\"quantity\":1,\"stock_quantity\":0,\"track_inventory\":0,\"custom_dimensions\":{\"width\":100,\"depth\":70,\"height\":90},\"custom_signature\":\"depth:70|height:90|width:100\",\"is_free_gift\":false,\"delivery_charge\":0,\"bundle_parent_id\":null,\"original_price\":null,\"short_description\":\"Mariot Made stainless steel work table with rear backsplash, left and right side splash, middle and bottom shelf, designed for professional kitchens, prep areas, hotels, restaurants, and commercial use. Made from AISI 304 18/10 stainless steel with Scotch-Brite finish for durability, hygiene, corrosion resistance, and easy cleaning. Features a 1.2 mm top, 100 mm splashes, 40 x 40 mm square legs, 1.5 mm thickness, adjustable feet, and UAE-built quality.\\n\",\"short_description_ar\":\"طاولة عمل من الستانلس ستيل المقاوم للصدأ من ماريوت، مزودة بحافة خلفية، وحواف جانبية يمنى ويسرى، ورف أوسط وسفلي، مصممة خصيصًا للمطابخ الاحترافية، ومناطق التحضير، والفنادق، والمطاعم، والاستخدامات التجارية. مصنوعة من الستانلس ستيل المقاوم للصدأ ٣٠٤ AISI ١٨/١٠، ومطلية بطبقة سكوتش برايت لضمان المتانة، والنظافة، ومقاومة التآكل، وسهولة التنظيف. تتميز بسطح بسماكة ١.٢ مم، وحواف بارتفاع ١٠٠ مم، وأرجل مربعة الشكل ٤٠ × ٤٠ مم، وسماكة ١.٥ مم، وقواعد قابلة للتعديل، وجودة تصنيع عالية في الإمارات العربية المتحدة.\",\"model\":\"MF19\"},{\"id\":57,\"variant_id\":null,\"name\":\"Work Table with Backsplash, Left Side Splash, Middle and Bottom Shelff\",\"name_ar\":\"طاولة عمل مزودة بحافة خلفية، وبحافة جانبية يسرى، ورف أوسط ورف سفلي\",\"slug\":\"work-table-with-backsplash,-left-side-splash,-middle-and-bottom-shelff\",\"price\":990,\"image\":\"https://api.mariotstore.com/uploads/1781770432495-172356348.webp\",\"brand\":\"MARIOT FABRICATION\",\"quantity\":1,\"stock_quantity\":0,\"track_inventory\":0,\"custom_dimensions\":{\"width\":100,\"depth\":70,\"height\":90},\"custom_signature\":\"depth:70|height:90|width:100\",\"is_free_gift\":false,\"delivery_charge\":0,\"bundle_parent_id\":null,\"original_price\":null,\"short_description\":\"Mariot Made stainless steel work table with rear backsplash, left side splash, middle and bottom shelf, designed for professional kitchens, prep areas, hotels, restaurants, and commercial use. Made from AISI 304 18/10 stainless steel with Scotch-Brite finish for durability, hygiene, corrosion resistance, and easy cleaning. Features a 1.2 mm top, 100 mm rear and left side splashes, 40 x 40 mm square legs, 1.5 mm thickness, adjustable feet, UAE-built quality.\\n\",\"short_description_ar\":\"طاولة عمل من الستانلس ستيل المقاوم للصدأ من ماريوت، مزودة بحافة خلفية وجانبية يسرى، ورف أوسط وسفلي، مصممة خصيصًا للمطابخ الاحترافية، ومناطق التحضير، والفنادق، والمطاعم، والاستخدامات التجارية. مصنوعة من الستانلس ستيل المقاوم للصدأ ٣٠٤ AISI ١٨/١٠، ومطلية بطبقة سكوتش برايت لضمان المتانة، والنظافة، ومقاومة التآكل، وسهولة التنظيف. تتميز بسطح بسماكة  ١.٢ مم، وحواف خلفية وجانبية يسرى بارتفاع ١٠٠ مم، وأرجل مربعة الشكل بقياس ٤٠ × ٤٠ مم، وسماكة ١.٥ مم، وقواعد قابلة للتعديل، وجودة تصنيع عالية في الإمارات العربية المتحدة.\",\"model\":\"MF16\"}]', 1980.00, 0.00, 99.00, 2079.00, '2026-06-20 19:42:23'),
